/* ------------------------------------------------------------------
   Maxfiy sozlamalarni web-papkadan TASHQARIDA saqlash (tavsiya etiladi).
   index.php turgan papkadan bir pog'ona yuqorida "akbartech.config.php"
   fayli bo'lsa, undagi qiymatlar yuqoridagilardan ustun turadi. Namuna:

     <?php return [
         'bot_token'       => '123456:ABC...',
         'admin_pass_hash' => '$2y$...',
         'setup_key'       => '...',
         'ai_key'          => '...',
     ];

   Shundan keyin yuqoridagi shu maydonlarni bo'sh ('') qoldirish mumkin.
   ------------------------------------------------------------------ */
$__external = dirname(__DIR__) . '/akbartech.config.php';
if (@is_file($__external) && @is_readable($__external)) {
    $__override = include $__external;
    if (is_array($__override)) {
        $CONFIG = array_replace($CONFIG, array_intersect_key($__override, $CONFIG));
    }
}
unset($__external, $__override);

ini_set('display_errors', $CONFIG['debug'] ? '1' : '0');
error_reporting($CONFIG['debug'] ? E_ALL : E_ALL & ~E_DEPRECATED & ~E_NOTICE);
date_default_timezone_set('Asia/Tashkent');

/**
 * Yonidagi faylni topadi, katta-kichik harfga qaramay
 * ("app.css" yuklashda "App.css" bo'lib qolsa ham ishlaydi).
 */
function local_file(string $name): ?string
{
    static $map = null;

    if ($map === null) {
        $map = [];
        foreach ((array) @scandir(__DIR__) as $entry) {
            if ($entry !== '.' && $entry !== '..') {
                $map[strtolower((string) $entry)] = (string) $entry;
            }
        }
    }

    return $map[strtolower($name)] ?? null;
}

function local_path(string $name): ?string
{
    $real = local_file($name);
    return $real === null ? null : __DIR__ . '/' . $real;
}

/** v3 moslik: barcha modullar endi shu faylning ichida. */
