/** Sozlamani o'qish: cfg('bot_token'). */
function cfg(string $key, $default = null)
{
    global $CONFIG;
    return $CONFIG[$key] ?? $default;
}

/**
 * Shablonlar bilan mos bo'lishi uchun: config('app.name').
 * 'app.' prefiksi olib tashlanadi va cfg() ga uzatiladi.
 */
function config(string $key, $default = null)
{
    if (str_starts_with($key, 'app.')) {
        return cfg(substr($key, 4), $default);
    }
    return cfg($key, $default);
}

/* ==================================================================
   ADMIN PANELDA O'ZGARTIRILADIGAN SOZLAMALAR (store/settings)
   Bot tokeni, AI kaliti va boshqalar — index.php ni tahrirlamasdan.
   ================================================================== */

function settings_all(): array
{
    if (!isset($GLOBALS['__settings_cache'])) {
        $GLOBALS['__settings_cache'] = store_read('settings');
    }
    return (array) $GLOBALS['__settings_cache'];
}

function settings_get(string $key, $default = null)
{
    $all = settings_all();
    return array_key_exists($key, $all) ? $all[$key] : $default;
}

function settings_set(array $patch): bool
{
    unset($GLOBALS['__settings_cache']);
    return store_update('settings', static function (array $all) use ($patch): array {
        foreach ($patch as $key => $value) {
            if ($value === null) {
                unset($all[$key]);
            } else {
                $all[$key] = $value;
            }
        }
        return $all;
    });
}

/** Amaldagi bot tokeni: admin panelda kiritilgani ustun. */
/**
 * Bot tokeni. Admin panelda saqlangan token faqat index.php dagi token
 * o'zgarmagan bo'lsa ishlatiladi — index.php da yangi token qo'yilsa, u ustun.
 */
function bot_token(): string
{
    $config = trim((string) cfg('bot_token', ''));
    $saved  = trim((string) settings_get('bot_token', ''));
    if ($saved !== '' && (string) settings_get('bot_token_cfg', '') === hash('sha256', $config)) {
        return $saved;
    }
    return $config !== '' ? $config : $saved;
}

/** Bot username: ulanishda Telegram'dan olingan → index.php dagi → bo'sh. */
function bot_username(): string
{
    $live = trim((string) settings_get('bot_username_live', ''));
    return $live !== '' ? $live : ltrim(trim((string) cfg('bot_username', '')), '@');
}

/** Bot tokeni yoki manzil o'zgargan bo'lsa — javob yuborilgandan keyin webhook va menyuni qayta sozlaydi. */
const BOT_AUTOCONNECT_RETRY = 600; // soniya

function bot_autoconnect(string $route): void
{
    if ($route !== 'app' || bot_token() === '' || !store_available()) {
        return;
    }
    if ((string) settings_get('bot_connected', '') === bot_fingerprint()) {
        return;
    }
    if (time() - (int) settings_get('bot_autoconnect_at', 0) < BOT_AUTOCONNECT_RETRY) {
        return;
    }
    if (!str_starts_with(bot_app_url(), 'https://')) {
        return;
    }
    settings_set(['bot_autoconnect_at' => time()]);
    register_shutdown_function(static function (): void {
        if (function_exists('fastcgi_finish_request')) {
            fastcgi_finish_request();
        }
        try {
            $result = bot_setup();
            if (empty($result['ok'])) {
                error_log('[AKBARTECH] bot autoconnect: ' . (string) ($result['error'] ?? ''));
            }
        } catch (Throwable $e) {
            error_log('[AKBARTECH] bot autoconnect: ' . $e->getMessage());
        }
    });
}

/** AI yordamchi sozlamalari (admin panel → config → standart). */
function ai_settings(): array
{
    $provider = (string) (settings_get('ai_provider') ?: cfg('ai_provider', 'gemini'));
    if (!in_array($provider, ['gemini', 'anthropic', 'openai'], true)) {
        $provider = 'gemini';
    }
    $defaults = [
        'gemini'    => 'gemini-3.8-flash',
        'anthropic' => 'claude-haiku-5-5',
        'openai'    => '',
    ];
    $model = trim((string) (settings_get('ai_model') ?: cfg('ai_model', '')));

    return [
        'enabled'    => (bool) settings_get('ai_enabled', true),
        'provider'   => $provider,
        'key'        => trim((string) (settings_get('ai_key') ?: cfg('ai_key', ''))),
        'model'      => $model !== '' ? $model : $defaults[$provider],
        'base_url'   => rtrim(trim((string) (settings_get('ai_base_url') ?: 'https://api.openai.com/v1')), '/'),
        'user_hour'  => max(1, (int) settings_get('ai_user_hour', 20)),
        'user_day'   => max(1, (int) settings_get('ai_user_day', 60)),
        'guest_day'  => max(0, (int) settings_get('ai_guest_day', 10)),
        'daily_cap'  => max(1, (int) settings_get('ai_daily_cap', 1500)),
        'in_bot'     => (bool) settings_get('ai_in_bot', true),
    ];
}

