/** "+998970008620" → "+998 97 000 86 20". */
function phone_pretty(string $phone): string
{
    $digits = preg_replace('/\D/', '', $phone) ?? '';
    if (strlen($digits) === 12 && str_starts_with($digits, '998')) {
        return sprintf('+998 %s %s %s %s', substr($digits, 3, 2), substr($digits, 5, 3), substr($digits, 8, 2), substr($digits, 10, 2));
    }
    return $phone;
}

/** Saytning to'liq manzili (https://domen/papka/...). */
function absolute_url(string $path): string
{
    $https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
        || strtolower((string) ($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '')) === 'https'
        || (string) ($_SERVER['SERVER_PORT'] ?? '') === '443';
    $host = preg_replace('/[^A-Za-z0-9.\-:\[\]]/', '', (string) ($_SERVER['HTTP_HOST'] ?? '')) ?? '';
    return ($https ? 'https' : 'http') . '://' . $host . $path;
}

function is_https(): bool
{
    return str_starts_with(absolute_url('/'), 'https://');
}

function send_json(array $data, int $status = 200): void
{
    if (!headers_sent()) {
        http_response_code($status);
        header('Content-Type: application/json; charset=UTF-8');
        header('Cache-Control: no-store, max-age=0');
        header('X-Content-Type-Options: nosniff');
    }
    echo json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
        | JSON_INVALID_UTF8_SUBSTITUTE) ?: '{}';
}

/** Javobni mijozga yuborib, skriptni fonda davom ettiradi. */
function finish_response(): void
{
    ignore_user_abort(true);
    if (function_exists('fastcgi_finish_request')) {
        @fastcgi_finish_request();
        return;
    }
    if (function_exists('litespeed_finish_request')) {
        @litespeed_finish_request();
        return;
    }
    @ob_end_flush();
    @flush();
}

/** IP manzildan anonim kalit (IP o'zi saqlanmaydi). */
function client_ip_key(): string
{
    $ip = (string) ($_SERVER['HTTP_CF_CONNECTING_IP'] ?? $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0');
    return 'ip:' . substr(hash('sha256', $ip . '|' . cfg('setup_key')), 0, 24);
}

/**
 * Oddiy "sirpanuvchi oyna" limiti. $limit ta urinish $window soniyada.
 * Ruxsat bo'lsa true qaytaradi va urinishni hisobga oladi.
 */
function rate_hit(string $bucket, string $key, int $limit, int $window): bool
{
    if (!store_available()) {
        return true;
    }
    $allowed = false;
    store_update('rate_' . preg_replace('/[^a-z0-9_]/', '', $bucket), static function (array $rows) use ($key, $limit, $window, &$allowed): array {
        $now = time();
        foreach ($rows as $k => $hits) {
            $rows[$k] = array_values(array_filter((array) $hits, static fn ($t): bool => $now - (int) $t < $window));
            if ($rows[$k] === []) {
                unset($rows[$k]);
            }
        }
        $mine = (array) ($rows[$key] ?? []);
        if (count($mine) < $limit) {
            $mine[] = $now;
            $rows[$key] = $mine;
            $allowed = true;
        }
        return $rows;
    });
    return $allowed;
}

/** Kontent va tarjimalar (data_source) — bir marta yuklanadi. */
function data_all(): array
{
    static $data = null;
    if ($data === null) {
        $data = data_source();
    }
    return $data;
}

/** Standart kontent + admin panelda saqlangan o'zgarishlar (store/content). */
function content_all(): array
{
    if (!isset($GLOBALS['__content_cache'])) {
        $base = (array) (data_all()['content'] ?? []);
        $saved = store_read('content');
        foreach (CONTENT_KEYS as $key) {
            if (isset($saved[$key]) && is_array($saved[$key])) {
                $base[$key] = $saved[$key];
            }
        }
        $GLOBALS['__content_cache'] = $base;
    }
    return (array) $GLOBALS['__content_cache'];
}

/** Admin paneldan kontent bo'limini saqlash. */
function content_save(string $key, array $value): bool
{
    if (!in_array($key, CONTENT_KEYS, true)) {
        return false;
    }
    unset($GLOBALS['__content_cache']);
    return store_update('content', static function (array $all) use ($key, $value): array {
        $all[$key] = $value;
        $all['updated_at'] = date('c');
        return $all;
    });
}

