/** Bosh sahifadagi "salomlashuv" o'rniga — har kirganda boshqacha matvatsion gap. */
function motivation_pick(): string
{
    $locale = lang_use();
    $tree   = (array) data_all()['lang'];
    $list   = (array) ($tree[$locale]['home']['motivation'] ?? []);

    if ($list === []) {
        $fallback = (string) cfg('locale', 'uz');
        $list = (array) ($tree[$fallback]['home']['motivation'] ?? []);
    }
    if ($list === []) {
        return '';
    }

    return (string) $list[array_rand($list)];
}

/* ==================================================================
   TARJIMA
   ================================================================== */

function lang_use(?string $locale = null): string
{
    static $current = null;

    if ($locale !== null) {
        $current = lang_sanitize($locale);
    }
    if ($current === null) {
        $current = lang_sanitize((string) cfg('locale', 'uz'));
    }
    return $current;
}

function lang_sanitize(?string $locale): string
{
    $locale = strtolower(substr((string) $locale, 0, 2));
    $supported = (array) cfg('locales', ['uz', 'en', 'ru']);
    return in_array($locale, $supported, true) ? $locale : (string) cfg('locale', 'uz');
}

/** Bitta tilning tekis (nuqtali) lug'ati. */
function lang_dict(?string $locale = null): array
{
    static $cache = [];
    $locale = lang_sanitize($locale ?? lang_use());

    if (isset($cache[$locale])) {
        return $cache[$locale];
    }

    $tree = (array) (data_all()['lang'][$locale] ?? []);
    $flat = [];
    lang_flatten($tree, '', $flat);

    // Kalit yetishmasa o'zbekchaga tushadi
    $fallback = (string) cfg('locale', 'uz');
    if ($locale !== $fallback) {
        $base = [];
        lang_flatten((array) (data_all()['lang'][$fallback] ?? []), '', $base);
        $flat += $base;
    }

    return $cache[$locale] = $flat;
}

function lang_flatten(array $tree, string $prefix, array &$out): void
{
    foreach ($tree as $key => $value) {
        $composed = $prefix === '' ? (string) $key : $prefix . '.' . $key;
        if (is_array($value)) {
            lang_flatten($value, $composed, $out);
        } else {
            $out[$composed] = (string) $value;
        }
    }
}

/** Tarjima: __('home.hi', ['name' => 'Akbar']). */
function __(string $key, array $replace = []): string
{
    $value = lang_dict()[$key] ?? $key;
    foreach ($replace as $search => $replacement) {
        $value = str_replace(':' . $search, (string) $replacement, $value);
    }
    return $value;
}

/** Tarjima + escape — shablonlarda shu ishlatiladi. */
function t(string $key, array $replace = []): string
{
    return e(__($key, $replace));
}

/** ['uz'=>.., 'en'=>.., 'ru'=>..] massividan joriy tildagisini oladi. */
function tr($value): string
{
    if ($value === null) {
        return '';
    }
    if (is_string($value)) {
        return $value;
    }

    $locale = lang_use();
    $fallback = (string) cfg('locale', 'uz');

    if (isset($value[$locale]))   { return (string) $value[$locale]; }
    if (isset($value[$fallback])) { return (string) $value[$fallback]; }

    $first = reset($value);
    return $first === false ? '' : (string) $first;
}

/* ==================================================================
   YORDAMCHI FUNKSIYALAR
   ================================================================== */

function e($value): string
{
    return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

/**
 * Ilova joylashgan papka. index.php qaysi manzilda bo'lsa, shu aniqlanadi —
 * domen ildizida ham, ichki papkada ham to'g'ri ishlaydi.
 */
function base_path(): string
{
    static $base = null;
    if ($base !== null) {
        return $base;
    }

    $script = (string) ($_SERVER['SCRIPT_NAME'] ?? '');
    $dir = rtrim(str_replace('\\', '/', dirname($script)), '/');

    return $base = ($dir === '/' ? '' : $dir);
}

/**
 * Fayl manzili. app.css va app.js shu faylning o'zida turadi va
 * ?r=asset orqali (kesh bilan) beriladi; boshqalari — papkadagi fayl.
 */
function asset(string $file): string
{
    $name = ltrim($file, '/');
    if (in_array($name, ['app.css', 'app.js'], true)) {
        return entry_url() . '?r=asset&f=' . $name . '&v=' . asset_version($name);
    }
    $real = local_file($name);
    if ($real !== null) {
        $name = $real;
    }
    return base_path() . '/' . $name . '?v=' . cfg('version', '1.0.0');
}

/** Kirish nuqtasi: /TezMind.uz/index.php */
function entry_url(): string
{
    return base_path() . '/index.php';
}

/** Marshrut manzili: route_url('screen', ['name' => 'about']) */
function route_url(string $route, array $params = []): string
{
    return entry_url() . '?' . http_build_query(['r' => $route] + $params);
}

/* ==================================================================
   IKONKALAR — Lucide, SVG holida ichkariga joylangan
   ================================================================== */

function icon_paths(): array
{
    static $paths = null;
    if ($paths === null) {
        $paths = ICONS;
    }
    return $paths;
}

function icon(string $name, int $size = 24, string $class = ''): string
{
    $paths = icon_paths()[$name] ?? icon_paths()['circle-check'];

    return sprintf(
        '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" '
        . 'stroke="currentColor" stroke-width="1.75" stroke-linecap="round" '
        . 'stroke-linejoin="round" aria-hidden="true" focusable="false">%s</svg>',
        e(trim('icon ' . $class)),
        $size,
        $size,
        $paths
    );
}

/* ==================================================================
   TELEGRAM IMZO TEKSHIRUVI
   Bu ilovaning xavfsizlik markazi. initData Telegram tomonidan
   imzolanadi; imzo to'g'ri bo'lmasa, foydalanuvchiga ishonilmaydi.
   ================================================================== */

function tg_verify(string $initData): ?array
{
    $token = bot_token();
    if ($initData === '' || $token === '') {
        return null;
    }

    $pairs = [];
    $hash = '';

    foreach (explode('&', $initData) as $chunk) {
        if ($chunk === '') {
            continue;
        }
        $parts = explode('=', $chunk, 2);
        $key = urldecode($parts[0]);
        $value = urldecode($parts[1] ?? '');

        if ($key === 'hash') {
            $hash = strtolower($value);
            continue;
        }
        $pairs[$key] = $value;
    }

    if ($hash === '' || $pairs === []) {
        return null;
    }

    /*
     * Telegram qoidasi: data-check-string — "hash" dan boshqa BARCHA maydonlar
     * (yangi "signature" maydoni ham shu jumladan), alifbo tartibida.
     * Eski mijozlar uchun "signature"siz variant ham tekshiriladi.
     */
    $secretKey = hash_hmac('sha256', $token, 'WebAppData', true);
    $check = static function (array $fields) use ($secretKey, $hash): bool {
        ksort($fields, SORT_STRING);
        $lines = [];
        foreach ($fields as $key => $value) {
            $lines[] = $key . '=' . $value;
        }
        return hash_equals(hash_hmac('sha256', implode("\n", $lines), $secretKey), $hash);
    };
    $valid = $check($pairs);
    if (!$valid && isset($pairs['signature'])) {
        $withoutSignature = $pairs;
        unset($withoutSignature['signature']);
        $valid = $check($withoutSignature);
    }
    if (!$valid) {
        return null;
    }
    unset($pairs['signature']);

    $authDate = (int) ($pairs['auth_date'] ?? 0);
    $ttl = (int) cfg('init_data_ttl', 86400);
    if ($ttl > 0 && ($authDate <= 0 || (time() - $authDate) > $ttl)) {
        return null;
    }

    $user = [];
    if (isset($pairs['user'])) {
        $decoded = json_decode($pairs['user'], true);
        if (is_array($decoded)) {
            $user = $decoded;
        }
    }

    if (!isset($user['id'])) {
        return null;
    }

    return ['verified' => true, 'user' => tg_normalize($user), 'auth_date' => $authDate];
}

/**
 * Imzo tekshiruvi natijasini eslab qoladi (5 daqiqada bir marta yoziladi).
 * Admin panel shu orqali "bot tokeni mos emas" muammosini ko'rsatadi.
 */
function tg_verify_stat(bool $ok): void
{
    $key = $ok ? 'tg_verify_ok_at' : 'tg_verify_fail_at';
    if (time() - (int) settings_get($key, 0) > 300) {
        settings_set([$key => time()]);
    }
}

function tg_normalize(array $user): array
{
    $clean = static function ($v) { return trim(strip_tags((string) $v)); };

    return [
        'id'            => (int) ($user['id'] ?? 0),
        'first_name'    => $clean($user['first_name'] ?? ''),
        'last_name'     => $clean($user['last_name'] ?? ''),
        'username'      => $clean($user['username'] ?? ''),
        'language_code' => substr($clean($user['language_code'] ?? ''), 0, 5),
        'is_premium'    => (bool) ($user['is_premium'] ?? false),
        'photo_url'     => tg_safe_photo((string) ($user['photo_url'] ?? '')),
    ];
}

/** Faqat Telegram serverlaridagi rasmlar sahifaga chiqariladi. */
function tg_safe_photo(string $url): string
{
    if ($url === '') {
        return '';
    }
    $parts = parse_url($url);
    if (($parts['scheme'] ?? '') !== 'https') {
        return '';
    }

    $host = strtolower($parts['host'] ?? '');
    foreach (['t.me', 'telegram.org', 'cdn.telegram.org', 'telesco.pe'] as $domain) {
        if ($host === $domain || str_ends_with($host, '.' . $domain)) {
            return $url;
        }
    }
    return '';
}

/* ==================================================================
   SAQLASH — JSON fayllar (store/*.json)

   Bu ilova endi 100% JSON fayllar orqali ishlaydi. Hech qanday
   ma'lumotlar bazasi (MySQL, SQLite) talab qilinmaydi va ishlatilmaydi.
   Barcha yozuvlar store/ papkasidagi JSON fayllarga saqlanadi:
     - store/users.json     — Telegram orqali kirgan foydalanuvchilar
     - store/stats.json     — kunlik tashriflar statistikasi
     - store/projects.json  — admin panelda qo'shilgan loyihalar
     - store/messages.json  — bildirishnomalar
     - store/reads.json     — kim qaysi xabarni o'qigan
     - store/videos.json    — video darsliklar
   ================================================================== */

/** Telegramdan tashqarida ochilganda — faqat ko'rsatish uchun, saqlanmaydi. */
function tg_guest(array $unsafe = []): array
{
    $user = tg_normalize($unsafe);
    $user['id'] = 0;
    if ($user['first_name'] === '') {
        $user['first_name'] = __('profile.guest_name');
    }
    return $user;
}

/**
 * Foydalanuvchini JSON'ga yozadi/yangilaydi va tashrifini belgilaydi.
 * Faqat imzosi tekshirilgan (haqiqiy Telegram) foydalanuvchilar uchun
 * chaqiriladi. Har so'rovda bir marta ishlaydi.
 */
function user_find(int $tgId): ?array
{
    if ($tgId <= 0) {
        return null;
    }
    $users = store_read('users');
    return $users[(string) $tgId] ?? null;
}

function user_touch(array $user, string $locale, string $theme): ?array
{
    $tgId = (int) ($user['id'] ?? 0);
    if ($tgId <= 0 || !store_available()) {
        return null;
    }

    $key   = (string) $tgId;
    $now   = date('c');
    $today = date('Y-m-d');
    $record = null;

    $ok = store_update('users', function (array $users) use (&$record, $key, $now, $user, $locale, $theme, $tgId) {
        $existing = $users[$key] ?? [
            'first_seen' => $now,
            'visits'     => 0,
            'avatar'     => '',
            'avatar_at'  => '',
            'prefs'      => json_encode(
                ['notifications' => true, 'haptics' => true, 'motion' => true],
                JSON_UNESCAPED_UNICODE
            ),
        ];

        $existing['id']         = $tgId;
        $existing['tg_id']      = $tgId;
        $existing['first_name'] = (string) ($user['first_name'] ?? '');
        $existing['last_name']  = (string) ($user['last_name'] ?? '');
        $existing['username']   = (string) ($user['username'] ?? '');
        $existing['photo_url']  = (string) ($user['photo_url'] ?? '');
        $existing['is_premium'] = !empty($user['is_premium']);
        $existing['language']   = (string) ($user['language_code'] ?? '');
        $existing['locale']     = $locale;
        $platform = preg_replace('/[^a-z0-9_.-]/i', '', (string) request_input('platform', ''));
        $client = preg_replace('/[^0-9.]/', '', (string) request_input('tg_version', ''));
        if ($platform !== '') { $existing['platform'] = mb_substr($platform, 0, 20); }
        if ($client !== '') { $existing['tg_version'] = mb_substr($client, 0, 10); }
        // Ko'rinish (theme) faqat foydalanuvchi o'zi tanlaganda saqlanadi —
        // aks holda standart ko'rinish o'zgarganda eski qiymat "yopishib" qoladi.
        if (empty($existing['theme_set'])) {
            $existing['theme'] = '';
        }
        $existing['visits']     = (int) ($existing['visits'] ?? 0) + 1;
        $existing['last_seen']  = $now;
        $existing['updated_at'] = $now;
        $existing += ['avatar' => '', 'avatar_at' => '', 'prefs' => '{}'];

        $users[$key] = $existing;
        $record = $existing;

        return $users;
    });

    if (!$ok) {
        return null;
    }

    visits_track($tgId, $today);

    return $record;
}

function user_save_prefs(int $tgId, string $locale, string $theme, array $prefs): bool
{
    if ($tgId <= 0 || !store_available()) {
        return false;
    }

    $key = (string) $tgId;

    return store_update('users', function (array $users) use ($key, $locale, $theme, $prefs) {
        if (!isset($users[$key])) {
            return $users;
        }

        $users[$key]['locale']     = $locale;
        $users[$key]['theme']      = $theme;
        $users[$key]['theme_set']  = true;
        $users[$key]['prefs']      = json_encode($prefs, JSON_UNESCAPED_UNICODE) ?: '{}';
        $users[$key]['updated_at'] = date('c');

        return $users;
    });
}

function user_forget(int $tgId): bool
{
    if ($tgId <= 0 || !store_available()) {
        return false;
    }

    $key = (string) $tgId;

    store_update('users', function (array $users) use ($key) {
        if (isset($users[$key])) {
            $avatar = (string) ($users[$key]['avatar'] ?? '');
            if ($avatar !== '') {
                avatar_delete($avatar);
            }
            unset($users[$key]);
        }
        return $users;
    });

    // Bot va AI'dagi izlari ham o'chiriladi (buyurtmalar — biznes yozuvi, qoladi).
    foreach (['reads', 'bot_leads', 'ai_threads'] as $store) {
        store_update($store, static function (array $rows) use ($key): array {
            unset($rows[$key]);
            return $rows;
        });
    }

    return true;
}

/** Kunlik statistika — oxirgi 90 kun saqlanadi (store/stats.json). */
function visits_track(int $tgId, string $day): void
{
    if ($tgId <= 0 || !store_available()) {
        return;
    }

    store_update('stats', function (array $stats) use ($tgId, $day) {
        $today = $stats[$day] ?? ['visits' => 0, 'users' => []];
        $today['visits'] = (int) ($today['visits'] ?? 0) + 1;

        $seen = (array) ($today['users'] ?? []);
        if (!in_array($tgId, $seen, true)) {
            $seen[] = $tgId;
        }
        $today['users'] = $seen;

        $stats[$day] = $today;

        if (count($stats) > 90) {
            krsort($stats);
            $stats = array_slice($stats, 0, 90, true);
            ksort($stats);
        }

        return $stats;
    });
}

/* ==================================================================
   PROFIL RASMI — Telegramdan yuklab, uploads/avatars ga saqlanadi
   ================================================================== */

/** Saqlangan yozuvdan ko'rsatiladigan rasm manzili. */
function user_avatar_url(array $rec): string
{
    $avatar = (string) ($rec['avatar'] ?? '');
    if ($avatar !== '' && strpos($avatar, '/') === false && strpos($avatar, '\\') === false) {
        return base_path() . '/uploads/avatars/' . rawurlencode($avatar);
    }
    return tg_safe_photo((string) ($rec['photo_url'] ?? ''));
}

/** Telegram Bot API chaqiruvi (rasm yuklash uchun). */
function tg_api(string $method, array $params = []): array
{
    $token = bot_token();
    if ($token === '' || !str_contains($token, ':')) {
        return ['ok' => false];
    }

    $url = 'https://api.telegram.org/bot' . $token . '/' . $method;
    $payload = http_build_query($params);

    if (function_exists('curl_init')) {
        $handle = curl_init($url);
        curl_setopt_array($handle, [
            CURLOPT_POST           => true,
            CURLOPT_POSTFIELDS     => $payload,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => 10,
        ]);
        $response = curl_exec($handle);
        curl_close($handle);
    } else {
        $response = @file_get_contents($url, false, stream_context_create([
            'http' => [
                'method'        => 'POST',
                'header'        => "Content-Type: application/x-www-form-urlencoded\r\n",
                'content'       => $payload,
                'timeout'       => 10,
                'ignore_errors' => true,
            ],
        ]));
    }

    $decoded = json_decode((string) $response, true);
    return is_array($decoded) ? $decoded : ['ok' => false];
}

function avatars_dir(): ?string
{
    $base = uploads_dir();
    if ($base === null) { return null; }

    $dir = $base . '/avatars';
    if (!is_dir($dir) && !@mkdir($dir, 0775, true) && !is_dir($dir)) {
        return null;
    }
    return $dir;
}

function avatar_delete(string $name): void
{
    if ($name === '' || strpos($name, '/') !== false || strpos($name, '\\') !== false) {
        return;
    }
    $dir = avatars_dir();
    if ($dir !== null && is_file($dir . '/' . $name)) {
        @unlink($dir . '/' . $name);
    }
}

/** Telegramdan eng katta profil rasmini yuklab, fayl nomini qaytaradi. */
function avatar_download(int $tgId): ?string
{
    $photos = tg_api('getUserProfilePhotos', ['user_id' => $tgId, 'limit' => 1]);
    if (empty($photos['ok']) || empty($photos['result']['photos'][0])) {
        return null;
    }

    $sizes  = (array) $photos['result']['photos'][0];
    $best   = end($sizes);
    $fileId = (string) ($best['file_id'] ?? '');
    if ($fileId === '') { return null; }

    $info = tg_api('getFile', ['file_id' => $fileId]);
    $path = (string) ($info['result']['file_path'] ?? '');
    if (empty($info['ok']) || $path === '') { return null; }

    $token = bot_token();
    $url   = 'https://api.telegram.org/file/bot' . $token . '/' . $path;

    if (function_exists('curl_init')) {
        $handle = curl_init($url);
        curl_setopt_array($handle, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => 15,
            CURLOPT_FOLLOWLOCATION => true,
        ]);
        $bytes = curl_exec($handle);
        curl_close($handle);
    } else {
        $bytes = @file_get_contents($url);
    }

    if ($bytes === false || $bytes === null || strlen((string) $bytes) < 64) {
        return null;
    }

    $dir = avatars_dir();
    if ($dir === null) { return null; }

    $ext = strtolower((string) pathinfo($path, PATHINFO_EXTENSION));
    if (!in_array($ext, ['jpg', 'jpeg', 'png', 'webp'], true)) {
        $ext = 'jpg';
    }
    $name = $tgId . '-' . substr(bin2hex(random_bytes(4)), 0, 8) . '.' . $ext;

    if (@file_put_contents($dir . '/' . $name, $bytes) === false) {
        return null;
    }
    @chmod($dir . '/' . $name, 0644);

    return $name;
}

/**
 * Foydalanuvchining profil rasmini yangilaydi. Rasmi bo'lsa — kuniga
 * bir marta, bo'lmasa — soatiga bir marta qayta uriniladi.
 */
function user_refresh_avatar(int $tgId): void
{
    if ($tgId <= 0 || !store_available()) { return; }

    $rec = user_find($tgId);
    if ($rec === null) { return; }

    $hasAvatar = ((string) ($rec['avatar'] ?? '')) !== '';
    $last = strtotime((string) ($rec['avatar_at'] ?? '')) ?: 0;

    if ($hasAvatar  && (time() - $last) < 86400) { return; }
    if (!$hasAvatar && (time() - $last) < 3600)  { return; }

    $file = avatar_download($tgId);
    $key = (string) $tgId;

    store_update('users', function (array $users) use ($key, $file) {
        if (!isset($users[$key])) {
            return $users;
        }

        if ($file !== null && $file !== '') {
            $old = (string) ($users[$key]['avatar'] ?? '');
            if ($old !== '' && $old !== $file) { avatar_delete($old); }
            $users[$key]['avatar']    = $file;
            $users[$key]['avatar_at'] = date('c');
        } else {
            $users[$key]['avatar_at'] = date('c');
        }

        return $users;
    });
}

/* ==================================================================
   SEANS — kim so'rayapti, qaysi tilda, qaysi ko'rinishda
   ================================================================== */

function request_header(string $name): string
{
    $key = 'HTTP_' . strtoupper(str_replace('-', '_', $name));
    if (isset($_SERVER[$key]) && $_SERVER[$key] !== '') {
        return (string) $_SERVER[$key];
    }

    // Ba'zi hostinglarda maxsus (X-...) sarlavhalar $_SERVER ga to'g'ri
    // tushmasligi mumkin — shu holat uchun zaxira yo'l.
    if (function_exists('getallheaders')) {
        foreach ((array) getallheaders() as $headerName => $headerValue) {
            if (strcasecmp((string) $headerName, $name) === 0) {
                return (string) $headerValue;
            }
        }
    }

    return '';
}

function request_body(): array
{
    static $body = null;
    if ($body !== null) {
        return $body;
    }

    $type = strtolower((string) ($_SERVER['CONTENT_TYPE'] ?? ''));
    if (str_contains($type, 'application/json')) {
        $raw = file_get_contents('php://input');
        $decoded = $raw === false || $raw === '' ? null : json_decode($raw, true);
        return $body = is_array($decoded) ? $decoded : [];
    }

    return $body = $_POST;
}

function request_input(string $key, $default = null)
{
    return request_body()[$key] ?? $_GET[$key] ?? $default;
}

/* ------------------------------------------------------------------
   Seans cookie'si: initData bir marta tasdiqlangach beriladi (7 kun).
   Hosting sarlavhani kesib tashlasa yoki ilova uzoq ochiq qolib initData
   eskirsa ham foydalanuvchi "mehmon"ga aylanib qolmaydi.
   ------------------------------------------------------------------ */
const SESSION_COOKIE = 'tm_sess';

function session_cookie_secret(): string
{
    return hash_hmac('sha256', 'tezmind-session-v1', bot_token() . '|' . __FILE__);
}

function session_cookie_uid(): int
{
    $raw = (string) ($_COOKIE[SESSION_COOKIE] ?? '');
    if (bot_token() === '' || !preg_match('/^(\d{1,15})\.(\d{10})\.([a-f0-9]{40})$/', $raw, $m)) {
        return 0;
    }
    if ((int) $m[2] < time()) {
        return 0;
    }
    $sig = substr(hash_hmac('sha256', $m[1] . '.' . $m[2], session_cookie_secret()), 0, 40);
    return hash_equals($sig, $m[3]) ? (int) $m[1] : 0;
}

function session_cookie_issue(int $uid): void
{
    if ($uid <= 0 || headers_sent() || bot_token() === '') {
        return;
    }
    $raw = (string) ($_COOKIE[SESSION_COOKIE] ?? '');
    if (session_cookie_uid() === $uid && preg_match('/^\d+\.(\d{10})\./', $raw, $m) && (int) $m[1] - time() > 3 * 86400) {
        return; // yangi va to'g'ri — qayta yozish shart emas
    }
    $exp = time() + 7 * 86400;
    $payload = $uid . '.' . $exp;
    $value = $payload . '.' . substr(hash_hmac('sha256', $payload, session_cookie_secret()), 0, 40);
    $secure = is_https();
    if (PHP_VERSION_ID >= 70300) {
        setcookie(SESSION_COOKIE, $value, [
            'expires'  => $exp,
            'path'     => '/',
            'secure'   => $secure,
            'httponly' => true,
            // Telegram Web (web.telegram.org) ilovani iframe ichida ochadi — u yerda None kerak
            'samesite' => $secure ? 'None' : 'Lax',
        ]);
    } else {
        setcookie(SESSION_COOKIE, $value, $exp, '/', '', $secure, true);
    }
    $_COOKIE[SESSION_COOKIE] = $value;
}

function session_resolve(): array
{
    static $session = null;
    if ($session !== null) {
        return $session;
    }

    // initData: avval sarlavhadan, topilmasa so'rov tanasidan.
    $initData = request_header('X-Telegram-Init-Data');
    if ($initData === '') {
        $initData = (string) request_input('init_data', '');
    }
    $result = tg_verify($initData);
    $verified = $result !== null;
    if ($initData !== '') {
        tg_verify_stat($verified);
    }

    // Imzosiz (tekshirilmagan) foydalanuvchi ma'lumoti — FAQAT ko'rsatish
    // uchun. Uni soxtalashtirish oson, shuning uchun unga tayanib hech
    // narsa yozilmaydi va o'chirilmaydi ("trusted" = false).
    $unsafe = [];
    $rawUnsafe = request_header('X-Telegram-Unsafe-User');
    if ($rawUnsafe === '') {
        $rawUnsafe = (string) request_input('unsafe_user', '');
    }
    if ($rawUnsafe !== '') {
        $decodedUnsafe = json_decode(base64_decode($rawUnsafe, true) ?: '', true);
        $unsafe = is_array($decodedUnsafe) ? $decodedUnsafe : [];
    }

    $trusted = false;
    $stored = null;

    // initData yo'q/eskirgan bo'lsa — avval tasdiqlangan seans cookie'si (boshqa akkaunt emasligini tekshirib)
    if (!$verified) {
        $cookieUid = session_cookie_uid();
        $unsafeId = (int) ($unsafe['id'] ?? 0);
        $cookieRecord = $cookieUid > 0 && ($unsafeId === 0 || $unsafeId === $cookieUid) ? user_find($cookieUid) : null;
        if (is_array($cookieRecord)) {
            $result = ['verified' => true, 'user' => tg_normalize($cookieRecord + ['id' => $cookieUid]), 'auth_date' => 0, 'via' => 'cookie'];
            $result['user']['language_code'] = (string) ($cookieRecord['language'] ?? '');
            $verified = true;
        }
    } elseif (!empty($result['user']['id'])) {
        session_cookie_issue((int) $result['user']['id']);
    }

    if ($verified) {
        $user = $result['user'];
        $stored = user_find((int) $user['id']);
        $trusted = true;
    } elseif ((int) ($unsafe['id'] ?? 0) > 0 && cfg('trust_unsigned', false) === true) {
        // Faqat hosting imzoni umuman o'tkazmaydigan holatlar uchun zaxira.
        $user = tg_normalize($unsafe);
        $stored = user_find((int) $user['id']);
        $trusted = true;
    } elseif ((int) ($unsafe['id'] ?? 0) > 0) {
        // Ismini ko'rsatamiz, lekin ID yo'q — hech narsa saqlanmaydi.
        $user = tg_normalize($unsafe);
        $user['id'] = 0;
    } else {
        $user = tg_guest($unsafe);
    }

    $prefs = [];
    if (is_array($stored) && isset($stored['prefs'])) {
        $decoded = json_decode((string) $stored['prefs'], true);
        $prefs = is_array($decoded) ? $decoded : [];
    }
    $prefs += ['notifications' => true, 'haptics' => true, 'motion' => true];

    // Til: so'rov -> sarlavha -> saqlangan -> Telegram tili -> standart
    $locale = null;
    foreach ([
        (string) request_input('locale', ''),
        request_header('X-App-Locale'),
        is_array($stored) ? (string) ($stored['locale'] ?? '') : '',
        (string) ($user['language_code'] ?? ''),
    ] as $candidate) {
        $normalized = strtolower(substr($candidate, 0, 2));
        if ($normalized !== '' && in_array($normalized, (array) cfg('locales'), true)) {
            $locale = $normalized;
            break;
        }
    }
    $locale = $locale ?? (string) cfg('locale', 'uz');

    // Ko'rinish: so'rov -> sarlavha -> foydalanuvchi o'zi tanlagan -> standart
    $theme = null;
    foreach ([
        (string) request_input('theme', ''),
        request_header('X-App-Theme'),
        (is_array($stored) && !empty($stored['theme_set'])) ? (string) ($stored['theme'] ?? '') : '',
    ] as $candidate) {
        if ($candidate !== '' && in_array($candidate, (array) cfg('themes'), true)) {
            $theme = $candidate;
            break;
        }
    }
    $theme = $theme ?? (string) cfg('theme', 'light');

    lang_use($locale);

    if (is_array($stored)) {
        $avatarUrl = user_avatar_url($stored);
        if ($avatarUrl !== '') {
            $user['photo_url'] = $avatarUrl;
        }
    }

    return $session = [
        'user'     => $user,
        'verified' => $verified,
        'trusted'  => $trusted,
        'record'   => $stored,
        'locale'   => $locale,
        'theme'    => $theme,
        'prefs'    => $prefs,
    ];
}

/**
 * Tashrifni yozadi. Faqat splash paytidagi bitta "session" so'rovida
 * chaqiriladi — har ekran almashganda emas (aks holda statistika
 * sun'iy ravishda ko'payib ketadi).
 */
function session_track(): array
{
    $session = session_resolve();
    if (!$session['trusted'] || (int) $session['user']['id'] <= 0) {
        return $session;
    }

    $fresh = user_touch($session['user'], $session['locale'], $session['theme']);
    if (is_array($fresh)) {
        $session['record'] = $fresh;
    }
    return $session;
}

/** Bu seans egasi admin (index.php dagi admin_tg_id) ekanmi? */
function session_is_admin(array $session): bool
{
    $adminId = (int) cfg('admin_tg_id', 0);
    return $adminId > 0 && !empty($session['verified'])
        && (int) ($session['user']['id'] ?? 0) === $adminId;
}

/** Salomlashish va profil uchun to'liq ism. */
function display_name(array $user): string
{
    $name = trim(((string) ($user['first_name'] ?? '')) . ' ' . ((string) ($user['last_name'] ?? '')));
    return $name !== '' ? $name : __('profile.guest_name');
}

/* ==================================================================
   SAQLASH — JSON fayllar
   Serverda pdo_sqlite bo'lmasligi mumkin, shuning uchun barcha
   ma'lumot oddiy JSON fayllarda saqlanadi. Hech qanday kengaytma
   yoki ma'lumotlar bazasi talab qilinmaydi.
   ================================================================== */

/** store/ papkasi — birinchi murojaatda o'zi yaratiladi. */
function store_dir(): ?string
{
    static $dir = null;
    static $failed = false;

    if ($failed)        { return null; }
    if ($dir !== null)  { return $dir; }

    // Mounted storage (Vercel → Supabase via akbfs://): no local dir, no .htaccess guard.
    if (defined('AKB_STORE_ROOT')) {
        return $dir = (string) AKB_STORE_ROOT;
    }

    $path = __DIR__ . '/store';

    if (!is_dir($path) && !@mkdir($path, 0775, true) && !is_dir($path)) {
        $failed = true;
        return null;
    }

    // Papka ichini tashqaridan ochib bo'lmasin (Apache 2.2 va 2.4).
    // Asosiy himoya baribir fayllarning o'zida: har biri .php bo'lib,
    // boshida "exit" turadi — nginx'da ham ichi ko'rinmaydi.
    $rules = "# TezMind v3\n<IfModule mod_authz_core.c>\n    Require all denied\n</IfModule>\n"
        . "<IfModule !mod_authz_core.c>\n    Order allow,deny\n    Deny from all\n</IfModule>\n";
    $guard = $path . '/.htaccess';
    if (!is_file($guard) || (string) @file_get_contents($guard) !== $rules) {
        @file_put_contents($guard, $rules);
    }
    if (!is_file($path . '/index.html')) {
        @file_put_contents($path . '/index.html', '');
    }

    return $dir = $path;
}

/** Rasm yuklanadigan papka. */
function uploads_dir(): ?string
{
    static $dir = null;
    static $failed = false;

    if ($failed)       { return null; }
    if ($dir !== null) { return $dir; }

    if (defined('AKB_UPLOADS_ROOT')) {
        return $dir = (string) AKB_UPLOADS_ROOT;
    }

    $path = __DIR__ . '/uploads';

    if (!is_dir($path) && !@mkdir($path, 0775, true) && !is_dir($path)) {
        $failed = true;
        return null;
    }

    // Papka mavjud bo'lsa-yu, lekin yozish huquqi bo'lmasa — buni ham
    // ushlaymiz, aks holda xato faqat fayl yozishga uringanda chiqadi.
    if (!is_writable($path)) {
        @chmod($path, 0775);
        if (!is_writable($path)) {
            $failed = true;
            return null;
        }
    }

    // Yuklangan fayl hech qachon kod sifatida bajarilmasin. Fayllar faqat
    // rasm kengaytmasi bilan saqlanadi; qo'shimcha ravishda PHP ishlovchisi
    // o'chiriladi. Faqat mod_mime direktivalari — hech bir hostingda 500 bermaydi.
    $rules = "# TezMind v3\n<IfModule mod_mime.c>\n"
        . "    RemoveHandler .php .phtml .php3 .php4 .php5 .php7 .php8 .phar .pl .py .cgi\n"
        . "    RemoveType .php .phtml .php3 .php4 .php5 .php7 .php8 .phar\n"
        . "</IfModule>\n";
    $guard = $path . '/.htaccess';
    if (!is_file($guard) || (string) @file_get_contents($guard) !== $rules) {
        @file_put_contents($guard, $rules);
    }

    return $dir = $path;
}

function upload_url(string $file): string
{
    if ($file === '') {
        return '';
    }
    // To'liq https havola (masalan Google Drive) — o'zgarishsiz
    if (preg_match('#^https://[^\s"<>]+$#i', $file)) {
        return $file;
    }
    if (img_cdn() !== '' && !is_file((uploads_dir() ?? __DIR__ . '/uploads') . '/' . $file)) {
        return img_cdn() . '/' . rawurlencode($file);
    }
    return base_path() . '/uploads/' . rawurlencode($file);
}

/** Har bir ma'lumot faylining boshidagi himoya qatori. */
const STORE_GUARD = "<?php http_response_code(404); exit; ?>\n";

/** Fayl nomi faqat harf, raqam va "_" dan iborat bo'lsin. */
function store_name(string $name): string
{
    return preg_replace('/[^a-z0-9_]/', '', strtolower($name)) ?: 'misc';
}

/**
 * Ma'lumotni o'qish. Fayllar store/<nom>.php ko'rinishida saqlanadi:
 * birinchi qatorda "exit" bor, shuning uchun ularni brauzerdan ochib
 * bo'lmaydi (nginx'da ham). Eski store/<nom>.json bo'lsa — avtomatik
 * yangi formatga ko'chiriladi va eskisi o'chiriladi.
 */
function store_read(string $name): array
{
    $dir = store_dir();
    if ($dir === null) {
        return [];
    }

    $name = store_name($name);
    $path = $dir . '/' . $name . '.php';

    if (!is_file($path)) {
        $legacy = $dir . '/' . $name . '.json';
        if (is_file($legacy)) {
            $decoded = json_decode((string) @file_get_contents($legacy), true);
            $data = is_array($decoded) ? $decoded : [];
            if (store_write($name, $data)) {
                @unlink($legacy);
            }
            return $data;
        }
        return [];
    }

    $raw = @file_get_contents($path);
    if ($raw === false || $raw === '') {
        return [];
    }
    if (str_starts_with($raw, '<?php')) {
        $cut = strpos($raw, "?>\n");
        $raw = $cut === false ? '' : substr($raw, $cut + 3);
    }

    $decoded = json_decode($raw, true);
    return is_array($decoded) ? $decoded : [];
}

/**
 * Ma'lumotni yozish. Avval vaqtinchalik faylga, keyin joyiga
 * ko'chiriladi — bir vaqtda kelgan so'rovlar faylni buzmaydi.
 */
function store_write(string $name, array $data): bool
{
    $dir = store_dir();
    if ($dir === null) {
        return false;
    }

    $name = store_name($name);
    $path = $dir . '/' . $name . '.php';
    $temp = $dir . '/' . $name . '.' . bin2hex(random_bytes(4)) . '.tmp';

    $json = json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
        | JSON_PRETTY_PRINT | JSON_INVALID_UTF8_SUBSTITUTE);

    if ($json === false) {
        return false;
    }

    // LOCK_EX is refused for stream wrappers; temp file + rename is atomic anyway.
    if (@file_put_contents($temp, STORE_GUARD . $json, fs_lock_flag($temp)) === false) {
        return false;
    }
    @chmod($temp, 0640);

    if (!@rename($temp, $path)) {
        @unlink($temp);
        return false;
    }

    return true;
}

function store_available(): bool
{
    return store_dir() !== null;
}

/** file_put_contents() refuses LOCK_EX on stream wrappers (e.g. akbfs://). */
function fs_lock_flag(string $path): int
{
    return str_contains($path, '://') ? 0 : LOCK_EX;
}

/** glob() that also works on stream-wrapper paths (glob() itself does not). */
function fs_glob(string $pattern): array
{
    if (!str_contains($pattern, '://')) {
        return (array) (@glob($pattern) ?: []);
    }
    $dir = dirname($pattern);
    $mask = basename($pattern);
    $out = [];
    foreach ((array) @scandir($dir) as $entry) {
        $entry = (string) $entry;
        if ($entry !== '.' && $entry !== '..' && fnmatch($mask, $entry)) {
            $out[] = $dir . '/' . $entry;
        }
    }
    return $out;
}

/**
 * Real local path for APIs that need one (CURLFile). Wrapper files are copied
 * to the temp dir; caller may unlink the copy when done.
 */
function fs_local_path(string $path): ?string
{
    if (!str_contains($path, '://')) {
        return is_file($path) ? $path : null;
    }
    $data = @file_get_contents($path);
    if ($data === false) {
        return null;
    }
    $ext = preg_replace('/[^a-z0-9]/', '', strtolower(pathinfo($path, PATHINFO_EXTENSION))) ?: 'bin';
    $local = sys_get_temp_dir() . '/akb-' . sha1($path) . '.' . $ext;
    return @file_put_contents($local, $data) === false ? null : $local;
}

/**
 * store/ dagi faylni xavfsiz o'zgartirish uchun.
 *
 * Nega kerak: bir nechta foydalanuvchi (masalan 1000 kishi) bir
 * vaqtda ilovani ochsa, har biri users.json'ni o'qib-o'zgartirib-
 * qayta yozadi. Qulfsiz holda ikkinchi so'rov birinchisining
 * yozganini ustidan bosib yuborishi mumkin edi — ya'ni foydalanuvchi
 * yoki tashrif hisobi yo'qolib ketardi. Bu funksiya faylni flock()
 * bilan qulflab, o'qish-o'zgartirish-yozish ketma-ketligini bitta
 * "bo'linmas" amal qiladi — 1 kishi ham, 1000 kishi bir vaqtda
 * kirsa ham, ma'lumot yo'qolmaydi.
 *
 * $mutator — joriy massivni qabul qilib, yangilangan massivni
 * qaytaruvchi funksiya.
 */
function store_update(string $name, callable $mutator): bool
{
    $dir = store_dir();
    if ($dir === null) {
        return false;
    }

    $lockPath = $dir . '/' . store_name($name) . '.lock';
    $handle = @fopen($lockPath, 'c');

    if ($handle === false) {
        // Qulf fayli ochilmasa ham ishlashda davom etamiz.
        $data = $mutator(store_read($name));
        return is_array($data) ? store_write($name, $data) : false;
    }

    $ok = false;
    if (flock($handle, LOCK_EX)) {
        $data = $mutator(store_read($name));
        $ok = is_array($data) ? store_write($name, $data) : false;
        flock($handle, LOCK_UN);
    }
    fclose($handle);

    return $ok;
}

/* ==================================================================
   FOYDALANUVCHILARNI HISOBGA OLISH
   Yozish mantig'i user_touch() va visits_track() ichida (yuqorida).
   ================================================================== */

/** Baza qatorini admin/ilova kutgan ko'rinishga o'tkazadi. */
function user_public(array $row): array
{
    $avatarUrl = user_avatar_url($row);
    $row['id'] = (int) ($row['tg_id'] ?? $row['id'] ?? 0);
    $row['is_premium'] = !empty($row['is_premium']);
    $row['photo_url'] = $avatarUrl;
    return $row;
}

/** Barcha foydalanuvchilar, oxirgi tashrif bo'yicha saralangan. */
function users_all(): array
{
    $users = array_values(store_read('users'));
    usort($users, static function (array $a, array $b): int {
        return strcmp((string) ($b['last_seen'] ?? ''), (string) ($a['last_seen'] ?? ''));
    });
    return array_map('user_public', $users);
}

function user_by_id(int $tgId): ?array
{
    $rec = user_find($tgId);
    return $rec !== null ? user_public($rec) : null;
}

/**
 * Grafik uchun kunlik ma'lumot.
 *
 * @return list<array{date:string,label:string,visits:int,users:int}>
 */
function stats_series(int $days = 14): array
{
    $byDay = [];
    foreach (store_read('stats') as $date => $day) {
        $byDay[(string) $date] = [
            'visits' => (int) ($day['visits'] ?? 0),
            'users'  => count((array) ($day['users'] ?? [])),
        ];
    }

    $series = [];
    for ($i = $days - 1; $i >= 0; $i--) {
        $date = date('Y-m-d', strtotime("-{$i} days"));
        $day = $byDay[$date] ?? ['visits' => 0, 'users' => 0];

        $series[] = [
            'date'   => $date,
            'label'  => date('d.m', strtotime($date)),
            'visits' => (int) $day['visits'],
            'users'  => (int) $day['users'],
        ];
    }

    return $series;
}

/** Dashboard uchun umumiy raqamlar. */
function stats_summary(): array
{
    $today   = date('Y-m-d');
    $weekAgo = date('Y-m-d', strtotime('-7 days'));

    $users = store_read('users');
    $stats = store_read('stats');

    $totalVisits = 0;
    $weekUsers   = [];
    $newThisWeek = 0;

    foreach ($stats as $date => $day) {
        $totalVisits += (int) ($day['visits'] ?? 0);
        if ($date >= $weekAgo) {
            foreach ((array) ($day['users'] ?? []) as $id) {
                $weekUsers[$id] = true;
            }
        }
    }

    $premium = 0;
    $locales = [];
    foreach ($users as $record) {
        if (!empty($record['is_premium'])) { $premium++; }
        $locale = (string) ($record['locale'] ?? 'uz');
        $locales[$locale] = ($locales[$locale] ?? 0) + 1;
        if (substr((string) ($record['first_seen'] ?? ''), 0, 10) >= $weekAgo) { $newThisWeek++; }
    }

    return [
        'users'        => count($users),
        'visits'       => $totalVisits,
        'today'        => (int) ($stats[$today]['visits'] ?? 0),
        'today_users'  => count((array) ($stats[$today]['users'] ?? [])),
        'week_users'   => count($weekUsers),
        'new_week'     => $newThisWeek,
        'premium'      => $premium,
        'locales'      => $locales,
        'projects'     => count(projects_all()),
        'messages'     => count(messages_all()),
    ];
}

/* ==================================================================
   LOYIHALAR
   Admin panel orqali qo'shilgan loyihalar store/projects.json da
   turadi. Fayl hali yo'q bo'lsa, data_source() dagilar boshlang'ich
   ro'yxat sifatida ishlatiladi.
   ================================================================== */

function projects_all(): array
{
    if (isset($GLOBALS['__projects_cache'])) {
        return $GLOBALS['__projects_cache'];
    }

    // Zaxira: saqlangan ro'yxat yoki data_source()
    $stored = store_read('projects');
    $list = $stored !== []
        ? array_values($stored)
        : (array) (content_all()['projects'] ?? []);

    return $GLOBALS['__projects_cache'] = $list;
}

function projects_save(array $list): bool
{
    unset($GLOBALS['__projects_cache']);

    $list = array_values($list);
    foreach ($list as $i => $project) {
        if ((string) ($project['slug'] ?? '') === '') {
            $list[$i]['slug'] = slugify((string) ($project['name'] ?? ''));
        }
    }

    return store_write('projects', $list);
}

function project_find(string $slug): ?array
{
    foreach (projects_all() as $project) {
        if ((string) ($project['slug'] ?? '') === $slug) {
            return $project;
        }
    }
    return null;
}

/** Nomdan xavfsiz slug yasaydi. */
function slugify(string $text): string
{
    $map = [
        'ʻ' => '', 'ʼ' => '', '’' => '', '‘' => '',
        'а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d','е'=>'e','ё'=>'e','ж'=>'j',
        'з'=>'z','и'=>'i','й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o',
        'п'=>'p','р'=>'r','с'=>'s','т'=>'t','у'=>'u','ф'=>'f','х'=>'h','ц'=>'c',
        'ч'=>'ch','ш'=>'sh','щ'=>'sh','ъ'=>'','ы'=>'y','ь'=>'','э'=>'e','ю'=>'yu','я'=>'ya',
    ];

    $text = mb_strtolower(trim($text), 'UTF-8');
    $text = strtr($text, $map);
    $text = preg_replace('/[^a-z0-9]+/u', '-', $text) ?? '';
    $text = trim($text, '-');

    return $text === '' ? 'loyiha-' . substr(bin2hex(random_bytes(3)), 0, 6) : $text;
}

/* ==================================================================
   VIDEO DARSLIKLAR
   Sof JSON fayl orqali ishlaydi — store/videos.json.
   Admin panelda qo'shiladi, mini app "Darsliklar" bo'limida ko'rinadi.
   ================================================================== */

function videos_all(): array
{
    return array_values(store_read('videos'));
}

function videos_save(array $list): bool
{
    return store_write('videos', array_values($list));
}

function video_find(string $id): ?array
{
    foreach (videos_all() as $video) {
        if ((string) ($video['id'] ?? '') === $id) {
            return $video;
        }
    }
    return null;
}

/**
 * Turli YouTube havola shakllaridan (watch, youtu.be, shorts, embed)
 * yoki bevosita 11 belgili ID'ning o'zidan video ID sini ajratib oladi.
 */
function youtube_id(string $url): ?string
{
    $url = trim($url);
    if ($url === '') {
        return null;
    }

    if (preg_match('/^[A-Za-z0-9_-]{11}$/', $url)) {
        return $url;
    }

    if (preg_match(
        '#(?:youtube(?:-nocookie)?\.com/(?:watch\?(?:.*&)?v=|embed/|shorts/|v/)|youtu\.be/)([A-Za-z0-9_-]{11})#i',
        $url,
        $m
    )) {
        return $m[1];
    }

    return null;
}

/** YouTube'ning tayyor eskiz rasmi — har doim mavjud bo'ladigan o'lcham. */
function youtube_thumb(string $videoId): string
{
    return 'https://i.ytimg.com/vi/' . rawurlencode($videoId) . '/hqdefault.jpg';
}

/** Darslikning muqova rasmi: admin yuklagan bo'lsa o'shani, aks holda YouTube'nikini. */
function video_cover_url(array $video): string
{
    $cover = (string) ($video['cover'] ?? '');
    if ($cover !== '') {
        return upload_url($cover);
    }

    $ytId = (string) ($video['youtube_id'] ?? '');
    return $ytId !== '' ? youtube_thumb($ytId) : '';
}

/* ==================================================================
   DARSLIK TAVSIYALARI — nomi bo'yicha qidirish va kunlik tanlov
   ================================================================== */

/** Matnni solishtirish uchun soddalashtiradi (apostroflar, belgilar). */
function lesson_norm(string $text): string
{
    $text = mb_strtolower($text, 'UTF-8');
    $text = str_replace(['ʻ', 'ʼ', '’', '‘', '`', "'", 'ё'], ['', '', '', '', '', '', 'е'], $text);
    $text = preg_replace('/[^\p{L}\p{N}]+/u', ' ', $text) ?? '';
    return trim($text);
}

/** "3-dars", "dars 3", "#3", "3 урок" kabi raqamni topadi. */
function lesson_number(string $text): ?int
{
    $t = mb_strtolower($text, 'UTF-8');
    if (preg_match('/(\d{1,3})\s*[-–.]?\s*(?:chi\s*)?(?:dars|darslik|урок|lesson|video|qism)/u', $t, $m)
        || preg_match('/(?:dars|darslik|урок|lesson|video|qism|#)\s*[-–№#]?\s*(\d{1,3})\b/u', $t, $m)) {
        return (int) $m[1];
    }
    return null;
}

/** Savolda darslik so'ralyaptimi. */
function lesson_intent(string $text): bool
{
    return (bool) preg_match('/dars|video|урок|видео|lesson|tutorial|kurs|курс|qayerdan boshla|nimadan boshla|с чего начать|where (do i|to) start/iu', $text);
}

/**
 * Savolga eng yaqin darsliklar (nomi va tavsifi bo'yicha).
 * @return list<array{video:array, score:int}>
 */
function lesson_match(string $question, int $limit = 3): array
{
    static $stop = ['dars', 'darslik', 'darsliklar', 'darsni', 'darslikni', 'video', 'videoni', 'haqida', 'qanday', 'nima',
        'menga', 'kerak', 'bormi', 'bor', 'ber', 'bering', 'berchi', 'korsat', 'korsating', 'iltimos', 'qaysi', 'uchun',
        'bilan', 'the', 'about', 'lesson', 'lessons', 'video', 'урок', 'уроки', 'урока', 'про', 'как', 'что', 'есть',
        'please', 'show', 'give', 'want', 'need', 'mavzu', 'mavzusi', 'shu', 'u', 'va', 'ham', 'and', 'для'];

    $videos = videos_all();
    if ($videos === []) {
        return [];
    }
    $number = lesson_number($question);
    $words = array_values(array_filter(
        explode(' ', lesson_norm($question)),
        static fn (string $w): bool => mb_strlen($w) >= 3 && !in_array($w, $stop, true)
            && !preg_match('/^(dars|урок|video|видео|lesson|boshla|начат|start|qayerdan|nimadan|boladi|bolad)/u', $w)
    ));

    $hits = [];
    foreach ($videos as $video) {
        $titles = implode(' ', array_map('strval', (array) ($video['title'] ?? [])));
        $title = lesson_norm($titles);
        $desc = lesson_norm(implode(' ', array_map('strval', (array) ($video['description'] ?? []))));
        $titleWords = explode(' ', $title);
        $score = 0;

        if ($number !== null && preg_match('/(?:^|\s)0*' . $number . '\s*(?:dars|урок|lesson|qism|$|\s)/u', $title . ' ')) {
            $score += 10;
        }
        foreach ($words as $w) {
            $best = 0;
            foreach ($titleWords as $tw) {
                if ($tw === $w) { $best = 4; break; }
                $min = min(mb_strlen($tw), mb_strlen($w));
                if ($min >= 4 && (str_starts_with($tw, mb_substr($w, 0, $min)) || str_starts_with($w, mb_substr($tw, 0, $min)))) {
                    $best = max($best, 3);
                }
            }
            if ($best === 0 && $desc !== '' && mb_strpos($desc, mb_substr($w, 0, max(4, mb_strlen($w) - 2))) !== false) {
                $best = 1;
            }
            $score += $best;
        }
        if ($score >= 3) {
            $hits[] = ['video' => $video, 'score' => $score];
        }
    }
    if ($number === null && $hits === [] && lesson_start_intent($question)) {
        $first = lesson_first();
        if ($first !== null) {
            $hits[] = ['video' => $first, 'score' => 8];
        }
    }
    usort($hits, static fn (array $a, array $b): int => $b['score'] <=> $a['score']);
    return array_slice($hits, 0, $limit);
}

/** "Qayerdan boshlay?" turidagi savol. */
function lesson_start_intent(string $text): bool
{
    return (bool) preg_match('/boshla|birinchi dars|noldan|yangi boshlov|начать|начина|новичк|с нуля|where (do i|to) start|beginner|first lesson/iu', $text);
}

/** Eng birinchi dars: nomida eng kichik raqam, bo'lmasa eng eski. */
function lesson_first(): ?array
{
    $course = course_lessons();
    if ($course !== []) {
        return $course[0];
    }
    $best = null;
    $bestNo = PHP_INT_MAX;
    $videos = videos_all();
    foreach ($videos as $video) {
        $no = lesson_number(tr($video['title'] ?? '')) ?? lesson_number((string) (($video['title'] ?? [])['uz'] ?? ''));
        if ($no !== null && $no < $bestNo) {
            $best = $video;
            $bestNo = $no;
        }
    }
    if ($best === null && $videos !== []) {
        usort($videos, static fn (array $a, array $b): int => strcmp((string) ($a['id'] ?? ''), (string) ($b['id'] ?? '')));
        $best = $videos[0];
    }
    return $best;
}

/** Har kuni boshqacha — sanaga bog'liq tasodifiy tartib. */
function lesson_daily(int $count = 3, string $salt = ''): array
{
    $videos = videos_all();
    usort($videos, static function (array $a, array $b) use ($salt): int {
        $day = date('Y-m-d') . $salt;
        return crc32($day . ($a['id'] ?? '')) <=> crc32($day . ($b['id'] ?? ''));
    });
    return array_slice($videos, 0, $count);
}

/* ==================================================================
   KURS — darslar ketma-ket ochiladi
   1) Videoni oxirigacha ko'radi  2) Vazifa yuboradi
   3) Admin "Qabul qilindi" bossa — keyingi dars ochiladi
   4) Hamma darslar tugasa — sertifikat beriladi
   ================================================================== */

const TASK_MAX_BYTES = 104857600;   // 100 MB
const COURSE_LEVELS  = ['beginner', 'intermediate', 'advanced'];

/** Darslar kurs tartibida: 1-dars birinchi. */
function course_lessons(): array
{
    $videos = videos_all();
    usort($videos, static function (array $a, array $b): int {
        $pa = (int) ($a['pos'] ?? 0);
        $pb = (int) ($b['pos'] ?? 0);
        if ($pa > 0 && $pb > 0 && $pa !== $pb) { return $pa <=> $pb; }
        if (($pa > 0) !== ($pb > 0)) { return $pa > 0 ? -1 : 1; }
        return strcmp((string) ($a['id'] ?? ''), (string) ($b['id'] ?? ''));
    });
    return array_values($videos);
}

/** Har bir darsga tartib raqamini (pos) yozib qo'yadi — admin tartibni o'zgartira oladi. */
function course_normalize(): array
{
    $lessons = course_lessons();
    $changed = false;
    foreach ($lessons as $i => $video) {
        if ((int) ($video['pos'] ?? 0) !== $i + 1) {
            $lessons[$i]['pos'] = $i + 1;
            $changed = true;
        }
    }
    if ($changed) {
        videos_save($lessons);
    }
    return $lessons;
}

/** Dars nomi, boshidagi "1-dars —" / "Lesson 1:" qismisiz (raqam alohida ko'rsatiladi). */
function lesson_title(array $video): string
{
    $title = tr($video['title'] ?? '');
    $clean = preg_replace('/^\s*(?:\d{1,3}\s*[-–.]?\s*(?:chi\s*)?(?:darslik|dars|урок|lesson)|(?:darslik|dars|урок|lesson)\s*[-–№#]?\s*\d{1,3})\s*[—–:\-.|)]*\s*/iu', '', $title);
    return is_string($clean) && trim($clean) !== '' ? trim($clean) : $title;
}

function course_title(): string
{
    $title = trim((string) settings_get('course_title', ''));
    return $title !== '' ? $title : 'Prompt engineering va AI coding';
}

function course_level_label(string $level): string
{
    return in_array($level, COURSE_LEVELS, true) ? __('course.lvl_' . $level) : '';
}

/** Foydalanuvchi progressi: watched / done (video id => vaqt). */
function progress_get(int $uid): array
{
    $row = store_read('progress')[(string) $uid] ?? [];
    return [
        'watched' => (array) ($row['watched'] ?? []),
        'done'    => (array) ($row['done'] ?? []),
    ];
}

function progress_mark(int $uid, string $field, string $videoId, bool $on = true): bool
{
    return store_update('progress', static function (array $all) use ($uid, $field, $videoId, $on): array {
        $key = (string) $uid;
        $row = $all[$key] ?? ['watched' => [], 'done' => []];
        $row[$field] = (array) ($row[$field] ?? []);
        if ($on) {
            $row[$field][$videoId] = $row[$field][$videoId] ?? date('c');
        } else {
            unset($row[$field][$videoId]);
        }
        $row['updated'] = date('c');
        $all[$key] = $row;
        return $all;
    });
}

/** Foydalanuvchining shu dars bo'yicha oxirgi vazifasi. */
function task_latest(int $uid, string $videoId): ?array
{
    foreach (store_read('tasks') as $task) {
        if ((int) ($task['uid'] ?? 0) === $uid && (string) ($task['video_id'] ?? '') === $videoId) {
            return $task;
        }
    }
    return null;
}

/**
 * Kurs holati. Har bir dars uchun state:
 *   done — tugallangan, review — vazifa tekshirilmoqda, rejected — qaytarilgan,
 *   watched — video ko'rildi (vazifa kutilmoqda), open — joriy dars, locked — yopiq.
 */
function course_state(int $uid, bool $isAdmin = false): array
{
    $lessons = course_lessons();
    $progress = $uid > 0 ? progress_get($uid) : ['watched' => [], 'done' => []];
    $latest = [];
    if ($uid > 0) {
        foreach (store_read('tasks') as $task) {
            if ((int) ($task['uid'] ?? 0) === $uid) {
                $vid = (string) ($task['video_id'] ?? '');
                $latest[$vid] = $latest[$vid] ?? $task;
            }
        }
    }

    $rows = [];
    $current = null;
    $doneCount = 0;
    foreach ($lessons as $i => $video) {
        $vid = (string) ($video['id'] ?? '');
        $task = $latest[$vid] ?? null;
        if (isset($progress['done'][$vid])) {
            $state = 'done';
            $doneCount++;
        } elseif ($current === null) {
            $current = $i;
            $status = (string) ($task['status'] ?? '');
            if ($status === 'pending') {
                $state = 'review';
            } elseif ($status === 'rejected') {
                $state = 'rejected';
            } elseif (isset($progress['watched'][$vid])) {
                $state = 'watched';
            } else {
                $state = 'open';
            }
        } else {
            $state = 'locked';
        }
        $rows[] = ['video' => $video, 'no' => $i + 1, 'state' => $state, 'task' => $task];
    }

    $total = count($rows);
    return [
        'lessons'  => $rows,
        'current'  => $current,
        'done'     => $doneCount,
        'total'    => $total,
        'complete' => $total > 0 && $doneCount >= $total,
    ];
}

/** Bitta dars holati (state + tartib raqami). */
function course_lesson(array $state, string $videoId): ?array
{
    foreach ($state['lessons'] as $row) {
        if ((string) ($row['video']['id'] ?? '') === $videoId) {
            return $row;
        }
    }
    return null;
}

/** Kim yopiq darsni ochmoqchi bo'lsa — qaysi darsni tugatish kerakligini aytamiz. */
function course_blocker(array $state): ?array
{
    return $state['current'] !== null ? $state['lessons'][$state['current']] : null;
}

/* ------------------------------------------------------------------
   Vazifa fayllari: store/files/ (tashqaridan ochilmaydi), tasodifiy nom,
   bajarilmaydigan .bin kengaytma. Faqat admin panel orqali beriladi.
   ------------------------------------------------------------------ */

function task_files_dir(): ?string
{
    $base = store_dir();
    if ($base === null) { return null; }
    $dir = $base . '/files';
    if (!is_dir($dir) && !@mkdir($dir, 0775, true) && !is_dir($dir)) {
        return null;
    }
    if (!is_file($dir . '/index.html')) {
        @file_put_contents($dir . '/index.html', '');
    }
    return $dir;
}

/** Bir bo'lak (chunk) hajmi — hostingning post_max_size chegarasiga mos. */
function task_chunk_size(): int
{
    $limit = 0;
    $raw = trim((string) ini_get('post_max_size'));
    if ($raw !== '' && $raw !== '0') {
        $num = (float) $raw;
        $unit = strtolower(substr($raw, -1));
        $limit = (int) ($unit === 'g' ? $num * 1073741824 : ($unit === 'm' ? $num * 1048576 : ($unit === 'k' ? $num * 1024 : $num)));
    }
    $chunk = 2 * 1048576;
    if ($limit > 0) {
        $chunk = min($chunk, (int) ($limit * 0.7));
    }
    return max(262144, $chunk);
}

function task_safe_name(string $name): string
{
    $name = trim(str_replace(["\0", '/', '\\'], '', $name));
    $name = preg_replace('/[\x00-\x1F\x7F]+/u', '', $name) ?? '';
    if ($name === '' || $name === '.' || $name === '..') { $name = 'fayl'; }
    return mb_substr($name, -120);
}

function task_detect_mime(string $path, string $name): string
{
    $mime = '';
    if (function_exists('finfo_open')) {
        $finfo = @finfo_open(FILEINFO_MIME_TYPE);
        if ($finfo) {
            $mime = (string) @finfo_file($finfo, $path);
            finfo_close($finfo);
        }
    }
    if ($mime === '' || $mime === 'application/octet-stream') {
        $ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
        $map = [
            'mp4' => 'video/mp4', 'mov' => 'video/quicktime', 'webm' => 'video/webm', 'mkv' => 'video/x-matroska',
            'jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png', 'gif' => 'image/gif', 'webp' => 'image/webp',
            'pdf' => 'application/pdf', 'zip' => 'application/zip', 'rar' => 'application/vnd.rar', '7z' => 'application/x-7z-compressed',
            'mp3' => 'audio/mpeg', 'm4a' => 'audio/mp4', 'ogg' => 'audio/ogg', 'wav' => 'audio/wav',
            'txt' => 'text/plain', 'html' => 'text/html', 'js' => 'text/javascript', 'css' => 'text/css', 'json' => 'application/json',
            'doc' => 'application/msword', 'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'ppt' => 'application/vnd.ms-powerpoint', 'pptx' => 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
            'xls' => 'application/vnd.ms-excel', 'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'fig' => 'application/octet-stream', 'psd' => 'image/vnd.adobe.photoshop',
        ];
        $mime = $map[$ext] ?? ($mime !== '' ? $mime : 'application/octet-stream');
    }
    return mb_substr($mime, 0, 120);
}

/** Eski, tugallanmagan bo'laklarni tozalash (1 kundan eski). */
function task_cleanup_parts(string $dir): void
{
    foreach (fs_glob($dir . '/*.part') as $file) {
        if (is_string($file) && @filemtime($file) < time() - 86400) {
            @unlink($file);
            @unlink(substr($file, 0, -5) . '.meta');
        }
    }
}

/**
 * Bo'lakma-bo'lak yuklash (100 MB gacha, istalgan fayl). Har bir so'rov
 * faylning keyingi qismini olib keladi: offset — shu paytgacha kelgan bayt.
 */
function task_upload_chunk(int $uid, string $uploadId, int $offset, int $size, string $name, string $videoId): array
{
    $dir = task_files_dir();
    if ($dir === null) {
        return ['ok' => false, 'error' => 'storage'];
    }
    if (!preg_match('/^[a-f0-9]{16,40}$/', $uploadId)) {
        return ['ok' => false, 'error' => 'bad_id'];
    }
    if ($size <= 0 || $size > TASK_MAX_BYTES) {
        return ['ok' => false, 'error' => 'too_big'];
    }

    $part = $dir . '/' . $uid . '_' . $uploadId . '.part';
    $metaPath = $dir . '/' . $uid . '_' . $uploadId . '.meta';

    if ($offset === 0) {
        task_cleanup_parts($dir);
        $meta = ['uid' => $uid, 'size' => $size, 'name' => task_safe_name($name), 'video_id' => $videoId, 'started' => time()];
        @file_put_contents($metaPath, json_encode($meta), fs_lock_flag($metaPath));
        @file_put_contents($part, '');
    }

    $meta = json_decode((string) @file_get_contents($metaPath), true);
    if (!is_array($meta) || (int) ($meta['uid'] ?? 0) !== $uid || (int) ($meta['size'] ?? 0) !== $size) {
        return ['ok' => false, 'error' => 'no_upload'];
    }

    clearstatcache(true, $part);
    $have = is_file($part) ? (int) filesize($part) : 0;
    if ($have !== $offset) {
        return ['ok' => false, 'error' => 'offset', 'have' => $have];
    }

    $in = fopen('php://input', 'rb');
    $out = fopen($part, 'ab');
    if ($in === false || $out === false) {
        return ['ok' => false, 'error' => 'storage'];
    }
    $written = 0;
    while (!feof($in)) {
        $buf = fread($in, 65536);
        if ($buf === false || $buf === '') { break; }
        $written += strlen($buf);
        if ($have + $written > $size) {
            fclose($in);
            fclose($out);
            @unlink($part);
            @unlink($metaPath);
            return ['ok' => false, 'error' => 'too_big'];
        }
        fwrite($out, $buf);
    }
    fclose($in);
    fclose($out);

    $have += $written;
    if ($have < $size) {
        return ['ok' => true, 'have' => $have, 'done' => false];
    }

    // Yakunlash: tasodifiy nom bilan saqlaymiz
    $token = bin2hex(random_bytes(16));
    $stored = $token . '.bin';
    if (!@rename($part, $dir . '/' . $stored)) {
        return ['ok' => false, 'error' => 'storage'];
    }
    @unlink($metaPath);
    $fileName = (string) $meta['name'];
    $record = [
        'uid'      => $uid,
        'file'     => $stored,
        'name'     => $fileName,
        'size'     => $have,
        'mime'     => task_detect_mime($dir . '/' . $stored, $fileName),
        'video_id' => (string) ($meta['video_id'] ?? ''),
        'created'  => time(),
    ];
    store_update('task_uploads', static function (array $all) use ($token, $record, $dir): array {
        // 2 kundan eski, ishlatilmagan fayllarni o'chiramiz
        foreach ($all as $key => $row) {
            if ((int) ($row['created'] ?? 0) < time() - 172800) {
                @unlink($dir . '/' . (string) ($row['file'] ?? ''));
                unset($all[$key]);
            }
        }
        $all[$token] = $record;
        return $all;
    });

    return ['ok' => true, 'have' => $have, 'done' => true, 'token' => $token];
}

function task_find(string $id): ?array
{
    foreach (store_read('tasks') as $task) {
        if ((string) ($task['id'] ?? '') === $id) {
            return $task;
        }
    }
    return null;
}

function task_pending_count(): int
{
    $n = 0;
    foreach (store_read('tasks') as $task) {
        if (($task['status'] ?? '') === 'pending') { $n++; }
    }
    return $n;
}

/** Vazifani yuborish (fayl yoki havola). */
function task_submit(array $session, string $videoId, string $kind, string $token, string $link, string $comment): array
{
    $user = $session['user'];
    $uid = !empty($session['trusted']) ? (int) $user['id'] : 0;
    if ($uid <= 0) {
        return ['ok' => false, 'error' => 'unauthorized'];
    }

    $state = course_state($uid, session_is_admin($session));
    $row = course_lesson($state, $videoId);
    if ($row === null) {
        return ['ok' => false, 'error' => 'not_found'];
    }
    if (!in_array($row['state'], ['open', 'watched', 'rejected'], true)) {
        return ['ok' => false, 'error' => 'not_allowed', 'state' => $row['state']];
    }
    if (!rate_hit('task_submit', 'u' . $uid, 15, 86400)) {
        return ['ok' => false, 'error' => 'rate_limited'];
    }

    $task = [
        'id'         => date('Ymd-His') . '-' . bin2hex(random_bytes(3)),
        'uid'        => $uid,
        'name'       => display_name($user),
        'username'   => (string) ($user['username'] ?? ''),
        'video_id'   => $videoId,
        'lesson'     => (int) $row['no'],
        'title'      => lesson_title($row['video']),
        'kind'       => $kind === 'link' ? 'link' : 'file',
        'link'       => '',
        'file'       => '',
        'file_name'  => '',
        'file_size'  => 0,
        'file_mime'  => '',
        'comment'    => mb_substr(trim($comment), 0, 1000),
        'status'     => 'pending',
        'note'       => '',
        'locale'     => (string) ($session['locale'] ?? 'uz'),
        'created_at' => date('c'),
    ];

    if ($task['kind'] === 'link') {
        $link = trim($link);
        if (!preg_match('~^https?://[^\s<>"]{3,}$~i', $link) || mb_strlen($link) > 600) {
            return ['ok' => false, 'error' => 'bad_link'];
        }
        $task['link'] = $link;
    } else {
        $uploads = store_read('task_uploads');
        $up = $uploads[$token] ?? null;
        if (!is_array($up) || (int) ($up['uid'] ?? 0) !== $uid) {
            return ['ok' => false, 'error' => 'no_file'];
        }
        $task['file'] = (string) $up['file'];
        $task['file_name'] = (string) $up['name'];
        $task['file_size'] = (int) $up['size'];
        $task['file_mime'] = (string) $up['mime'];
        store_update('task_uploads', static function (array $all) use ($token): array {
            unset($all[$token]);
            return $all;
        });
    }

    $ok = store_update('tasks', static function (array $all) use ($task): array {
        array_unshift($all, $task);
        return array_slice($all, 0, 5000);
    });
    if (!$ok) {
        return ['ok' => false, 'error' => 'storage'];
    }

    task_notify_admin($task);
    return ['ok' => true, 'state' => 'review', 'task' => ['id' => $task['id']]];
}

/** Adminga Telegram orqali: yangi vazifa keldi. */
function task_notify_admin(array $task): void
{
    $adminId = (int) cfg('admin_tg_id', 0);
    if ($adminId <= 0 || bot_token() === '') { return; }
    $who = h((string) $task['name']) . ((string) $task['username'] !== '' ? ' (@' . h((string) $task['username']) . ')' : '');
    $what = $task['kind'] === 'link'
        ? '🔗 ' . h((string) $task['link'])
        : '📎 ' . h((string) $task['file_name']) . ' · ' . task_size_label((int) $task['file_size']);
    $text = "📥 <b>Yangi vazifa</b>\n\n👤 " . $who
        . "\n📚 " . (int) $task['lesson'] . '-dars — ' . h((string) $task['title'])
        . "\n" . $what
        . ((string) $task['comment'] !== '' ? "\n💬 " . h(mb_substr((string) $task['comment'], 0, 300)) : '');
    bot_send($adminId, $text, ['inline_keyboard' => [[
        ['text' => '✅ Tekshirish', 'web_app' => ['url' => absolute_url(base_path() . '/admin.php?tg=1&p=tasks')]],
    ]]]);
}

function task_size_label(int $bytes): string
{
    if ($bytes >= 1048576) { return number_format($bytes / 1048576, 1, '.', '') . ' MB'; }
    if ($bytes >= 1024) { return (int) round($bytes / 1024) . ' KB'; }
    return $bytes . ' B';
}

/**
 * Admin qarori. accept — dars tugallanadi, keyingisi ochiladi; reject — izoh bilan qaytariladi.
 * Hamma darslar tugasa — sertifikat yozuvi yaratiladi (rasmi admin panelda chiziladi).
 */
function task_review(string $id, string $decision, string $note): array
{
    $task = task_find($id);
    if ($task === null) {
        return ['ok' => false, 'error' => 'not_found'];
    }
    $accept = $decision === 'accept';
    $note = mb_substr(trim($note), 0, 600);

    store_update('tasks', static function (array $all) use ($id, $accept, $note): array {
        foreach ($all as $i => $row) {
            if ((string) ($row['id'] ?? '') === $id) {
                $all[$i]['status'] = $accept ? 'accepted' : 'rejected';
                $all[$i]['note'] = $note;
                $all[$i]['reviewed_at'] = date('c');
            }
        }
        return $all;
    });

    $uid = (int) $task['uid'];
    $vid = (string) $task['video_id'];
    $result = ['ok' => true, 'status' => $accept ? 'accepted' : 'rejected'];

    if ($accept) {
        progress_mark($uid, 'watched', $vid);
        progress_mark($uid, 'done', $vid);
    }

    $state = course_state($uid);
    $c = course_bot_copy((string) ($task['locale'] ?? 'uz'));
    $lessonNo = (int) $task['lesson'];

    if ($accept) {
        $next = course_blocker($state);
        if ($state['complete']) {
            $cert = cert_ensure_course($uid, (string) $task['name']);
            $result['cert'] = cert_public($cert);
            bot_send($uid, sprintf($c['all_done'], $lessonNo), course_open_keyboard($c, ''));
        } elseif ($next !== null) {
            $nextVid = (string) ($next['video']['id'] ?? '');
            bot_send($uid, sprintf($c['accepted'], $lessonNo, (int) $next['no'], h(lesson_title($next['video']))),
                course_open_keyboard($c, 'video-' . $nextVid));
        }
    } else {
        bot_send($uid, sprintf($c['rejected'], $lessonNo, $note !== '' ? "\n\n💬 " . h($note) : ''),
            course_open_keyboard($c, 'video-' . $vid));
    }

    return $result;
}

function task_delete(string $id): bool
{
    $task = task_find($id);
    if ($task === null) { return false; }
    $dir = task_files_dir();
    if ($dir !== null && (string) ($task['file'] ?? '') !== '' && preg_match('/^[a-f0-9]{32}\.bin$/', (string) $task['file'])) {
        @unlink($dir . '/' . $task['file']);
    }
    return store_update('tasks', static function (array $all) use ($id): array {
        return array_values(array_filter($all, static fn (array $row): bool => (string) ($row['id'] ?? '') !== $id));
    });
}

function course_open_keyboard(array $c, string $open): array
{
    return ['inline_keyboard' => [[['text' => $c['open_btn'], 'web_app' => ['url' => bot_app_url($open)]]]]];
}

/** Bot xabarlari (foydalanuvchi tilida). */
function course_bot_copy(string $locale): array
{
    $all = [
        'uz' => [
            'accepted' => "✅ <b>%d-dars vazifangiz qabul qilindi!</b>\n\n🔓 %d-dars ochildi — «%s».\nDavom eting, siz zo‘r ketyapsiz! 🚀",
