/* ------------------------------------------------------------------
   SERTIFIKAT VA TASHAKKURNOMA
   Rasm admin panelda (brauzerda, canvas) chiziladi va shu yerga
   yuklanadi; keyin bot orqali yuboriladi va ilovada ko'rsatiladi.
   ------------------------------------------------------------------ */

function certs_all(): array
{
    return array_values(store_read('certificates'));
}

function cert_find(string $id): ?array
{
    foreach (certs_all() as $cert) {
        if ((string) ($cert['id'] ?? '') === $id) {
            return $cert;
        }
    }
    return null;
}

function cert_next_number(): string
{
    $max = 0;
    foreach (certs_all() as $cert) {
        if (preg_match('/(\d+)$/', (string) ($cert['number'] ?? ''), $m)) {
            $max = max($max, (int) $m[1]);
        }
    }
    return 'TM-' . date('Y') . '-' . str_pad((string) ($max + 1), 4, '0', STR_PAD_LEFT);
}

/** Yangi hujjat yozuvi (rasmsiz). */
function cert_create(int $uid, string $type, string $name, string $reason): array
{
    $cert = [
        'id'        => date('Ymd-His') . '-' . bin2hex(random_bytes(3)),
        'uid'       => $uid,
        'type'      => $type === 'appreciation' ? 'appreciation' : 'certificate',
        'name'      => mb_substr(trim($name), 0, 60),
        'course'    => course_title(),
        'lessons'   => count(course_lessons()),
        'reason'    => mb_substr(trim($reason), 0, 400),
        'number'    => cert_next_number(),
        'date'      => date('Y-m-d'),
        'image'     => '',
        'seen'      => false,
        'sent'      => false,
        'issued_at' => date('c'),
    ];
    store_update('certificates', static function (array $all) use ($cert): array {
        array_unshift($all, $cert);
        return $all;
    });
    return $cert;
}

/** Kurs tugaganda — bitta sertifikat (takrorlanmaydi). */
function cert_ensure_course(int $uid, string $name): array
{
    foreach (certs_all() as $cert) {
        if ((int) ($cert['uid'] ?? 0) === $uid && ($cert['type'] ?? '') === 'certificate') {
            return $cert;
        }
    }
    $lead = store_read('bot_leads')[(string) $uid] ?? [];
    $user = store_read('users')[(string) $uid] ?? [];
    $full = trim((string) ($user['first_name'] ?? '') . ' ' . (string) ($user['last_name'] ?? ''));
    if ($full === '') { $full = trim((string) ($lead['name'] ?? '')); }
    return cert_create($uid, 'certificate', $full !== '' ? $full : $name, '');
}

/** Canvas uchun ma'lumot (admin JS shu bilan rasm chizadi). */
function cert_public(array $cert): array
{
    return [
        'id'      => (string) $cert['id'],
        'type'    => (string) $cert['type'],
        'name'    => (string) $cert['name'],
        'course'  => (string) ($cert['course'] ?? course_title()),
        'lessons' => (int) ($cert['lessons'] ?? 0),
        'reason'  => (string) ($cert['reason'] ?? ''),
        'number'  => (string) $cert['number'],
        'date'    => (string) $cert['date'],
    ];
}

/** Admin yuklagan rasmni saqlaydi va bot orqali yuboradi. */
function cert_attach_image(string $id, string $tmpPath): array
{
    $cert = cert_find($id);
    if ($cert === null) {
        return ['ok' => false, 'error' => 'not_found'];
    }
    $info = @getimagesize($tmpPath);
    if (!is_array($info) || !in_array((int) $info[2], [IMAGETYPE_JPEG, IMAGETYPE_PNG], true) || $info[0] < 800) {
        return ['ok' => false, 'error' => 'bad_image'];
    }
    $dir = uploads_dir();
    if ($dir === null) {
        return ['ok' => false, 'error' => 'storage'];
    }
    $file = 'cert-' . bin2hex(random_bytes(10)) . ((int) $info[2] === IMAGETYPE_PNG ? '.png' : '.jpg');
    if (!@move_uploaded_file($tmpPath, $dir . '/' . $file) && !@copy($tmpPath, $dir . '/' . $file)) {
        return ['ok' => false, 'error' => 'storage'];
    }
    @chmod($dir . '/' . $file, 0644);
    $old = (string) ($cert['image'] ?? '');

    store_update('certificates', static function (array $all) use ($id, $file): array {
        foreach ($all as $i => $row) {
            if ((string) ($row['id'] ?? '') === $id) {
                $all[$i]['image'] = $file;
                $all[$i]['seen'] = false;
            }
        }
        return $all;
    });
    if ($old !== '' && preg_match('/^cert-[a-f0-9]{20}\.(jpg|png)$/', $old)) {
        @unlink($dir . '/' . $old);
    }

    $cert['image'] = $file;
    $sent = cert_send($cert);
    return ['ok' => true, 'sent' => $sent, 'url' => upload_url($file)];
}

/** Botdan rasm (siqilgan ko'rinish) + asl fayl (hujjat) sifatida yuboradi. */
function cert_send(array $cert): bool
{
    $uid = (int) ($cert['uid'] ?? 0);
    $dir = uploads_dir();
    if ($uid <= 0 || $dir === null || (string) ($cert['image'] ?? '') === '' || bot_token() === '') {
        return false;
    }
    $path = $dir . '/' . $cert['image'];
    $lead = store_read('bot_leads')[(string) $uid] ?? [];
    $user = store_read('users')[(string) $uid] ?? [];
    $locale = (string) ($user['locale'] ?? $lead['lang'] ?? 'uz');
    $c = course_bot_copy(in_array($locale, ['uz', 'ru', 'en'], true) ? $locale : 'uz');

    $caption = ($cert['type'] ?? '') === 'appreciation'
        ? sprintf($c['thanks'], h((string) $cert['name']), h((string) ($cert['reason'] ?: 'TezMind.uz jamoasi faolligingiz va a’lo natijalaringiz uchun minnatdorchilik bildiradi.')), h((string) $cert['number']))
        : sprintf($c['cert'], h((string) $cert['name']), h((string) ($cert['course'] ?? course_title())), h((string) $cert['number']));

    $keyboard = ['inline_keyboard' => [[['text' => $c['cert_btn'], 'web_app' => ['url' => bot_app_url('certs')]]]]];
    $photo = bot_api_upload('sendPhoto', [
        'chat_id'      => $uid,
        'caption'      => $caption,
        'parse_mode'   => 'HTML',
        'reply_markup' => json_encode($keyboard, JSON_UNESCAPED_UNICODE),
    ], 'photo', $path);
    $base = ($cert['type'] ?? '') === 'appreciation' ? 'TezMind-tashakkurnoma' : 'TezMind-sertifikat';
    bot_api_upload('sendDocument', [
        'chat_id' => $uid,
        'caption' => $c['original'],
    ], 'document', $path, $base . '-' . preg_replace('/[^A-Za-z0-9-]/', '', (string) $cert['number']) . '.' . pathinfo($path, PATHINFO_EXTENSION));

    $ok = !empty($photo['ok']);
    if ($ok) {
        store_update('certificates', static function (array $all) use ($cert): array {
            foreach ($all as $i => $row) {
                if ((string) ($row['id'] ?? '') === (string) $cert['id']) {
                    $all[$i]['sent'] = true;
                    $all[$i]['sent_at'] = date('c');
                }
            }
            return $all;
        });
    }
    return $ok;
}

function cert_delete(string $id): bool
{
    $cert = cert_find($id);
    if ($cert === null) { return false; }
    $dir = uploads_dir();
    $img = (string) ($cert['image'] ?? '');
    if ($dir !== null && $img !== '' && preg_match('/^cert-[a-f0-9]{20}\.(jpg|png)$/', $img)) {
        @unlink($dir . '/' . $img);
    }
    return store_update('certificates', static function (array $all) use ($id): array {
        return array_values(array_filter($all, static fn (array $row): bool => (string) ($row['id'] ?? '') !== $id));
    });
}

/** Foydalanuvchining tayyor hujjatlari (ilova uchun). */
function certs_for_user(int $uid): array
{
    if ($uid <= 0) { return []; }
    $out = [];
    foreach (certs_all() as $cert) {
        if ((int) ($cert['uid'] ?? 0) !== $uid || (string) ($cert['image'] ?? '') === '') { continue; }
        $out[] = [
            'id'     => (string) $cert['id'],
            'type'   => (string) $cert['type'],
            'number' => (string) $cert['number'],
            'name'   => (string) $cert['name'],
            'url'    => upload_url((string) $cert['image']),
            'abs'    => absolute_url(upload_url((string) $cert['image'])),
            'seen'   => !empty($cert['seen']),
            'date'   => (string) $cert['date'],
        ];
    }
    return $out;
}

function cert_mark_seen(int $uid, string $id): bool
{
    return store_update('certificates', static function (array $all) use ($uid, $id): array {
        foreach ($all as $i => $row) {
            if ((string) ($row['id'] ?? '') === $id && (int) ($row['uid'] ?? 0) === $uid) {
                $all[$i]['seen'] = true;
            }
        }
        return $all;
    });
}

/** Telegram'ga fayl yuklash (multipart). */
function bot_api_upload(string $method, array $params, string $field, string $path, string $filename = ''): array
{
    $token = bot_token();
    $path = fs_local_path($path) ?? '';
    if ($token === '' || $path === '' || !function_exists('curl_init') || !class_exists('CURLFile')) {
        return ['ok' => false, 'description' => 'upload unavailable'];
    }
    $url = 'https://api.telegram.org/bot' . $token . '/' . $method;
    $mime = str_ends_with(strtolower($path), '.png') ? 'image/png' : 'image/jpeg';
    $params[$field] = new CURLFile($path, $mime, $filename !== '' ? $filename : basename($path));
    $handle = curl_init($url);
    curl_setopt_array($handle, [
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => $params,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_CONNECTTIMEOUT => 8,
        CURLOPT_TIMEOUT        => 60,
    ]);
    $response = curl_exec($handle);
    curl_close($handle);
    $decoded = json_decode((string) $response, true);
    return is_array($decoded) ? $decoded : ['ok' => false, 'description' => 'no response'];
}

/* ==================================================================
   XABARLAR (bildirishnomalar)
   ================================================================== */

function messages_all(): array
{
    $list = array_values(store_read('messages'));
    usort($list, static function (array $a, array $b): int {
        return strcmp((string) ($b['created_at'] ?? ''), (string) ($a['created_at'] ?? ''));
    });
    return $list;
}

function messages_save(array $list): bool
{
    return store_write('messages', array_values($list));
}

/** Foydalanuvchi o'qigan xabarlar ro'yxati. */
function reads_of(int $tgId): array
{
    if ($tgId <= 0) { return []; }

    $reads = store_read('reads');
    return (array) ($reads[(string) $tgId] ?? []);
}

function message_mark_read(int $tgId, string $messageId): bool
{
    if ($tgId <= 0 || $messageId === '' || !store_available()) {
        return false;
    }

    $key = (string) $tgId;

    return store_update('reads', function (array $reads) use ($key, $messageId) {
        $mine = (array) ($reads[$key] ?? []);
        if (!in_array($messageId, $mine, true)) {
            $mine[] = $messageId;
            $reads[$key] = $mine;
        }
        return $reads;
    });
}

function messages_mark_all_read(int $tgId): bool
{
    if ($tgId <= 0 || !store_available()) { return false; }

    $ids = array_map(
        static fn (array $m): string => (string) ($m['id'] ?? ''),
        messages_all()
    );
    $ids = array_values(array_filter($ids));

    return store_update('reads', function (array $reads) use ($tgId, $ids) {
        $reads[(string) $tgId] = $ids;
        return $reads;
    });
}

/* ==================================================================
   BUYURTMALAR — mijozning "Loyiha buyurtma qilish" arizalari
   store/orders.json faylida saqlanadi.
   ================================================================== */

const ORDER_STATUSES = ['new', 'review', 'agreed', 'done'];
const ORDER_MIN_DESCRIPTION = 10;   // belgi
const ORDER_COOLDOWN = 180;         // soniya: bitta foydalanuvchi uchun arizalar orasi

/** Status kodlari -> admin panelda ko'rsatiladigan nom va rang. */
function order_statuses(): array
{
    return [
        'new'    => ['label' => 'Yangi',                'tone' => 'blue'],
        'review' => ['label' => 'Ko\'rib chiqilmoqda',  'tone' => 'amber'],
        'agreed' => ['label' => 'Kelishildi',            'tone' => 'green'],
        'done'   => ['label' => 'Yopildi',               'tone' => 'gray'],
    ];
}

/** Barcha buyurtmalar, eng yangisi birinchi. */
function orders_all(): array
{
    $list = array_values(store_read('orders'));
    usort($list, static function (array $a, array $b): int {
        return strcmp((string) ($b['created_at'] ?? ''), (string) ($a['created_at'] ?? ''));
    });
    return $list;
}

/** "Yangi" statusidagi buyurtmalar soni — dashboard va nav belgisi uchun. */
function orders_new_count(): int
{
    $count = 0;
    foreach (orders_all() as $order) {
        if ((string) ($order['status'] ?? 'new') === 'new') {
            $count++;
        }
    }
    return $count;
}

function order_find(string $id): ?array
{
    if ($id === '') { return null; }
    $order = store_read('orders')[$id] ?? null;
    return is_array($order) ? $order : null;
}

/**
 * Yangi buyurtma yaratadi. Barcha maydonlar serverda qayta
 * tekshiriladi (frontend tekshiruviga ishonilmaydi) va spamdan
 * himoya qilinadi — bitta foydalanuvchi 3 daqiqada bittadan ortiq
 * ariza yubora olmaydi. Bir xil "idem" kaliti bilan kelgan so'rov
 * yangi buyurtma yaratmaydi (takror bosish, tarmoq uzilishi).
 *
 * @return array{ok: bool, id?: string, error?: string, fields?: array, duplicate?: bool}
 */
function order_create(array $data): array
{
    if (!store_available()) {
        return ['ok' => false, 'error' => 'store_unavailable'];
    }

    $tgId = (int) ($data['tg_id'] ?? 0);
    $name = trim((string) ($data['name'] ?? ''));
    $description = trim((string) ($data['description'] ?? ''));
    $fields = [];

    if ($name === '' || mb_strlen($name) > 120) {
        $fields['name'] = 'invalid';
    }
    if (mb_strlen($description) < ORDER_MIN_DESCRIPTION) {
        $fields['description'] = 'invalid';
    }
    if (mb_strlen($description) > 2000) {
        $description = mb_substr($description, 0, 2000);
    }

    // Telegram username — faqat tasdiqlangan profildan (formada maydon yo'q)
    $username = ltrim(trim((string) ($data['username'] ?? '')), '@');
    if (!preg_match('/^[A-Za-z0-9_]{4,32}$/', $username)) {
        $username = '';
    }

    // Xizmat turi ixtiyoriy: xizmat kartasidan kelgan bo'lsa saqlanadi
    $serviceId = mb_substr(trim((string) ($data['service'] ?? '')), 0, 40);
    $serviceName = '';
    $service = $serviceId !== '' ? service_find($serviceId) : null;
    if ($service !== null) {
        $serviceName = (string) ($service['title']['uz'] ?? tr($service['title'] ?? ''));
    } else {
        $serviceId = '';
    }

    // Telefon raqam — majburiy: +, raqam, bo'sh joy, - va (); kamida 7 ta raqam
    $contact = mb_substr(trim(strip_tags((string) ($data['contact'] ?? ''))), 0, 30);
    $digits = (int) preg_match_all('/[0-9]/', $contact);
    if (!preg_match('/^\+?[0-9\s\-()]{7,24}$/', $contact) || $digits < 7 || $digits > 15) {
        $fields['contact'] = 'invalid';
    }

    if ($fields !== []) {
        return ['ok' => false, 'error' => 'validation', 'fields' => $fields];
    }

    $phone  = $contact;
    $budget = mb_substr(trim(strip_tags((string) ($data['budget'] ?? ''))), 0, 60);

    // Loyiha nomi mijozdan olinmaydi — slug bo'yicha serverda topiladi.
    $project = content_project(mb_substr(trim((string) ($data['project_slug'] ?? '')), 0, 120));
    $projectSlug = $project !== null ? (string) $project['slug'] : '';
    $projectName = $project !== null ? mb_substr((string) ($project['name'] ?? ''), 0, 160) : '';

    // Takror yuborishdan himoya: mijoz har forma uchun bitta kalit yuboradi.
    $idem = strtolower(trim((string) ($data['idem'] ?? '')));
    if (!preg_match('/^[a-f0-9]{16,64}$/', $idem)) {
        $idem = '';
    }

    $id = bin2hex(random_bytes(8));
    $order = [
        'id'           => $id,
        'tg_id'        => $tgId,
        'name'         => $name,
        'username'     => $username,
        'phone'        => $phone,
        'contact'      => $contact,
        'service'      => $serviceId,
        'service_name' => $serviceName,
        'budget'       => $budget,
        'deadline'     => '',
        'description'  => $description,
        'project_slug' => $projectSlug,
        'project_name' => $projectName,
        'idem'         => $idem,
        'status'       => 'new',
        'created_at'   => date('c'),
        'updated_at'   => date('c'),
    ];

    // Tekshiruv va yozuv bitta qulf ostida — parallel so'rovlar ikkita buyurtma yaratmaydi.
    $result = null;
    $saved = store_update('orders', static function (array $orders) use ($order, $id, $tgId, $idem, &$result): array {
        $now = time();
        foreach ($orders as $existing) {
            if ($idem !== '' && (string) ($existing['idem'] ?? '') === $idem) {
                $result = ['ok' => true, 'id' => (string) ($existing['id'] ?? ''), 'duplicate' => true];
                return $orders;
            }
        }
        if ($tgId > 0) {
            foreach ($orders as $existing) {
                if ((int) ($existing['tg_id'] ?? 0) !== $tgId) {
                    continue;
                }
                $age = $now - (int) strtotime((string) ($existing['created_at'] ?? ''));
                if ($age >= 0 && $age < ORDER_COOLDOWN) {
                    $result = ['ok' => false, 'error' => 'rate_limited'];
                    return $orders;
                }
            }
        }
        $orders[$id] = $order;
        $result = ['ok' => true, 'id' => $id];
        return $orders;
    });

    if (!$saved || $result === null) {
        return ['ok' => false, 'error' => 'save_failed'];
    }
    if (!empty($result['ok']) && empty($result['duplicate'])) {
        order_notify_admin($order);
    }

    return $result;
}

function order_set_status(string $id, string $status): bool
{
    if ($id === '' || !in_array($status, ORDER_STATUSES, true) || !store_available()) {
        return false;
    }

    return store_update('orders', function (array $orders) use ($id, $status) {
        if (!isset($orders[$id])) {
            return $orders;
        }
        $orders[$id]['status'] = $status;
        $orders[$id]['updated_at'] = date('c');
        return $orders;
    });
}

function order_delete(string $id): bool
{
    if ($id === '' || !store_available()) {
        return false;
    }

    return store_update('orders', function (array $orders) use ($id) {
        unset($orders[$id]);
        return $orders;
    });
}

/**
 * Yangi buyurtma kelganda adminga Telegram orqali darhol xabar
 * yuboradi (agar $CONFIG['admin_tg_id'] sozlangan bo'lsa). Xabar
 * yetib bormasa ham ariza baribir saqlanadi — admin panelda ko'rinadi.
 */
function order_notify_admin(array $order): void
{
    $adminId = (int) cfg('admin_tg_id', 0);
    if ($adminId <= 0) {
        return;
    }

    $tgId     = (int) ($order['tg_id'] ?? 0);
    $username = (string) ($order['username'] ?? '');
    $lines = ['🆕 <b>Yangi buyurtma</b> · ' . e((string) cfg('name')), '', '👤 Ism: ' . e((string) $order['name'])];

    // Lichka: username bo'lsa t.me havola, bo'lmasa ID orqali profil havolasi
    if ($username !== '')                      { $lines[] = '💬 Telegram: <a href="https://t.me/' . e($username) . '">@' . e($username) . '</a>'; }
    if ($tgId > 0)                             { $lines[] = '🆔 Lichka: <a href="tg://user?id=' . $tgId . '">' . e((string) $order['name']) . '</a> · <code>' . $tgId . '</code>'; }
    if (($order['phone'] ?? '') !== '')        { $lines[] = '📞 Telefon: <code>' . e((string) $order['phone']) . '</code>'; }
    if (($order['budget'] ?? '') !== '')       { $lines[] = '💰 Budjet: ' . e((string) $order['budget']); }
    if (($order['service_name'] ?? '') !== '') { $lines[] = '🧩 Xizmat: ' . e((string) $order['service_name']); }
    if (($order['project_name'] ?? '') !== '') { $lines[] = '📦 Loyiha: ' . e((string) $order['project_name']); }

    $lines[] = '';
    $lines[] = '📝 ' . e((string) $order['description']);

    $buttons = [];
    if ($username !== '') {
        $buttons[] = [['text' => '💬 Lichkaga yozish', 'url' => 'https://t.me/' . $username]];
    }
    $buttons[] = [['text' => '📦 Buyurtmalar', 'url' => absolute_url(base_path() . '/admin.php?p=orders')]];

    tg_api('sendMessage', [
        'chat_id'      => $adminId,
        'text'         => implode("\n", $lines),
        'parse_mode'   => 'HTML',
        'disable_web_page_preview' => true,
        'reply_markup' => json_encode(['inline_keyboard' => $buttons], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
    ]);
}

/** Bitta foydalanuvchining buyurtmalari (profil ekrani uchun). */
function orders_for_user(int $tgId): array
{
    if ($tgId <= 0) { return []; }
    return array_values(array_filter(
        orders_all(),
        static fn (array $o): bool => (int) ($o['tg_id'] ?? 0) === $tgId
    ));
}

/** Xabarlar ro'yxati, har biriga "o'qilgan" belgisi qo'shilgan holda. */
function messages_for_user(int $tgId): array
{
    $read = $tgId > 0 ? reads_of($tgId) : [];

    return array_map(static function (array $message) use ($read): array {
        $message['read'] = in_array((string) ($message['id'] ?? ''), $read, true);
        return $message;
    }, messages_all());
}

function unread_count(int $tgId): int
{
    if ($tgId <= 0) {
        return 0;
    }

    $read = reads_of($tgId);
    $count = 0;

    foreach (messages_all() as $message) {
        if (!in_array((string) ($message['id'] ?? ''), $read, true)) {
            $count++;
        }
    }

    return $count;
}

/** Ko'rsatish uchun "2 soat oldin" ko'rinishidagi vaqt. */
function time_ago(string $iso): string
{
    $timestamp = strtotime($iso);
    if ($timestamp === false) {
        return '';
    }

    $diff = time() - $timestamp;

    if ($diff < 60)     { return __('time.now'); }
    if ($diff < 3600)   { return __('time.minutes', ['n' => (int) floor($diff / 60)]); }
    if ($diff < 86400)  { return __('time.hours', ['n' => (int) floor($diff / 3600)]); }
    if ($diff < 604800) { return __('time.days', ['n' => (int) floor($diff / 86400)]); }

    return date('d.m.Y', $timestamp);
}

/* ==================================================================
   EKRANLARNI CHIZISH
   ================================================================== */

/** Shablon chaqiruvchi: view('screens.home', [...]). */
function view(string $name, array $data = []): string
{
    $fn = 'view_' . str_replace('.', '_', $name);
    return function_exists($fn) ? $fn($data) : '';
}

/** Bitta ekranni chizadi va unga seans ma'lumotlarini uzatadi. */
function render_screen(string $name, array $session, array $extra = []): string
{
    return view('screens.' . $name, array_merge([
        'session'  => $session,
        'user'     => $session['user'],
        'verified' => $session['verified'],
        'locale'   => $session['locale'],
        'theme'    => $session['theme'],
        'prefs'    => $session['prefs'],
        'trusted'  => $session['trusted'] ?? false,
        'record'   => $session['record'] ?? null,
        'is_admin' => session_is_admin($session),
        'name'     => display_name($session['user']),
    ], $extra));
}

