/** Kun vaqtiga qarab salomlashuv kaliti. */
function greet_key(): string
{
    $hour = (int) date('G');
    if ($hour >= 5 && $hour < 12)  { return 'home.greet.morning'; }
    if ($hour >= 12 && $hour < 18) { return 'home.greet.day'; }
    if ($hour >= 18 && $hour < 23) { return 'home.greet.evening'; }
    return 'home.greet.night';
}

/** Foydalanuvchi bosh harflari. */
function user_initials(array $user): string
{
    $initials = mb_strtoupper(
        mb_substr(trim((string) ($user['first_name'] ?? '')), 0, 1)
        . mb_substr(trim((string) ($user['last_name'] ?? '')), 0, 1)
    );
    return trim($initials) === '' ? 'A' : $initials;
}

/** Loyihalarni "tanlangan"lari birinchi bo'ladigan tartibda qaytaradi. */
function projects_sorted(): array
{
    $list = content_projects();
    usort($list, static function (array $a, array $b): int {
        return (int) !empty($b['featured']) <=> (int) !empty($a['featured']);
    });
    return $list;
}

