/** Brend yozuvi: AKBAR + TECH (ikkinchi qism aksent rangda). */
function brand_word(): string
{
    // Logodagi kabi: birinchi "A" ko'ndalang chiziqsiz (Λ), AKBAR — kumush, TECH — ko'k
    $lambda = '<svg class="bw__l" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M2 20 10 2.2l8 17.8" fill="none" stroke="currentColor" stroke-width="4.2" stroke-linejoin="miter" stroke-linecap="butt"/></svg>';
    return '<span class="bw" aria-label="AKBARTECH"><span class="bw__silver">' . $lambda . 'KBAR</span><em>TECH</em></span>';
}

