function cta_button(string $labelKey, string $attrs, string $class = ''): string
{
    return '<button type="button" class="cta ' . e($class) . '" ' . $attrs . ' data-press>'
        . '<span class="cta__label" data-i18n="' . e($labelKey) . '">' . t($labelKey) . '</span>'
        . '<span class="cta__arrow" aria-hidden="true">' . icon('arrow-up-right', 18) . '</span>'
        . '</button>';
}

