            <?php $pjImg = $cover === '' ? pic(project_image_key($p), '', '(min-width: 960px) 420px, 100vw') : ''; ?>
            <?php if ($cover !== ''): ?>
                <img class="pj__bg" src="<?= e(upload_url($cover)) ?>" alt="" aria-hidden="true" loading="lazy" decoding="async">
                <img class="pj__img" src="<?= e(upload_url($cover)) ?>" alt="<?= e((string) ($p['name'] ?? '')) ?>" loading="lazy" decoding="async">
            <?php elseif ($pjImg !== ''): ?>
                <?= $pjImg ?>
            <?php else: ?>
                <span class="pj__glyph"><?= icon((string) ($p['icon'] ?? 'sparkles'), 34) ?></span>
            <?php endif; ?>
            <span class="pj__tags">
                <span class="tag tag--glass"><?= e(project_cat_label($p)) ?></span>
                <?php if ($status !== ''): ?>
                    <span class="tag tag--<?= e($status) ?>" data-i18n="project.status.<?= e($status) ?>"><?= t('project.status.' . $status) ?></span>
                <?php endif; ?>
            </span>
            <span class="pj__go" aria-hidden="true"><?= icon('arrow-up-right', 18) ?></span>
        </span>
        <span class="pj__body">
            <span class="pj__name"><?= e((string) ($p['name'] ?? '')) ?></span>
            <span class="pj__tag"><?= e(tr($p['tagline'] ?? '')) ?></span>
