/** Profil egasining avatari (rasm yoki bosh harflar). */
function owner_avatar(string $class = ''): string
{
    $photo = profile_photo_url();
    $name  = (string) (content_profile()['name'] ?? '');
    if ($photo !== '') {
        return '<span class="oava ' . e($class) . '"><img src="' . e($photo) . '" alt="' . e($name) . '" width="96" height="96" loading="lazy" decoding="async"></span>';
    }
    return '<span class="oava oava--text ' . e($class) . '" role="img" aria-label="' . e($name) . '"><b>' . e(profile_initials()) . '</b></span>';
}

