/* ------------------------------------------------------------------
   BITTA LOYIHA
   ------------------------------------------------------------------ */
function view_screens_project(array $__d = []): string
{
    extract($__d, EXTR_SKIP);
    $accent  = (string) ($project['accent'] ?? '#1677FF');
    $accent2 = (string) ($project['accent_2'] ?? '#83C8FF');
    $metrics = array_values(array_filter((array) ($project['metrics'] ?? []), static fn ($m): bool => is_array($m) && trim((string) ($m['value'] ?? '')) !== ''));
    $stack   = (array) ($project['stack'] ?? []);
    $cover   = (string) ($project['cover'] ?? '');
    $shots   = array_values(array_filter((array) ($project['shots'] ?? []), static fn ($s): bool => (string) $s !== ''));
    $link    = (string) ($project['link'] ?? '');
    $status  = project_status($project);
    $year    = trim((string) ($project['year'] ?? ''));
    $host    = strtolower((string) parse_url($link, PHP_URL_HOST));
    $linkKey = in_array($host, ['t.me', 'telegram.me'], true) ? 'project.open_tg'
        : (str_contains($host, 'youtu') ? 'project.watch' : 'project.demo');
    $linkIcon = $linkKey === 'project.open_tg' ? 'send' : ($linkKey === 'project.watch' ? 'youtube' : 'external-link');
    ob_start();
    ?>
<section class="screen screen--stack" data-screen="project" data-slug="<?= e($project['slug']) ?>"
         id="screen-project" tabindex="-1" style="--p1: <?= e($accent) ?>; --p2: <?= e($accent2) ?>;">
    <div class="screen__inner">

        <?php $phImg = $cover === '' ? pic(project_image_key($project), '', '(min-width: 960px) 760px, 100vw', true) : ''; ?>
        <div class="phero reveal<?= ($cover !== '' || $phImg !== '') ? ' has-img' : '' ?>">
            <?php if ($cover !== ''): ?>
                <img class="phero__bg" src="<?= e(upload_url($cover)) ?>" alt="" aria-hidden="true" decoding="async">
                <img class="phero__img" src="<?= e(upload_url($cover)) ?>" alt="<?= e((string) $project['name']) ?>" decoding="async" fetchpriority="high">
            <?php elseif ($phImg !== ''): ?>
                <?= $phImg ?>
            <?php else: ?>
                <span class="phero__mesh" aria-hidden="true"></span>
                <span class="phero__tile"><?= icon((string) ($project['icon'] ?? 'sparkles'), 40) ?></span>
            <?php endif; ?>
        </div>

        <header class="phead reveal">
            <div class="phead__meta">
                <span class="tag tag--glass"><?= e(project_cat_label($project)) ?></span>
                <?php if ($status !== ''): ?>
                    <span class="tag tag--<?= e($status) ?>" data-i18n="project.status.<?= e($status) ?>"><?= t('project.status.' . $status) ?></span>
                <?php endif; ?>
                <?php if ($year !== ''): ?>
                    <span class="tag tag--glass"><?= icon('calendar', 12) ?><?= e($year) ?></span>
                <?php endif; ?>
                <?php if (!empty($project['featured'])): ?>
                    <span class="tag tag--accent"><?= icon('star', 12) ?><span data-i18n="project.featured"><?= t('project.featured') ?></span></span>
                <?php endif; ?>
            </div>
            <h1 class="phead__name"><?= e((string) $project['name']) ?></h1>
            <p class="phead__tagline"><?= e(tr($project['tagline'] ?? '')) ?></p>
        </header>

        <div class="actions reveal">
            <?= cta_button('project.order_button', 'data-order="' . e((string) $project['slug']) . '"', 'cta--wide') ?>
            <?php if ($link !== ''): ?>
                <a class="btn btn--glass" href="<?= e($link) ?>" target="_blank" rel="noopener" data-link data-press>
                    <?= icon($linkIcon, 15) ?><span data-i18n="<?= e($linkKey) ?>"><?= t($linkKey) ?></span>
                </a>
            <?php endif; ?>
        </div>

        <?php if ($metrics !== []): ?>
            <div class="kpis kpis--accent reveal">
                <?php foreach ($metrics as $metric): ?>
                    <?php $mLabel = isset($metric['label']) ? tr($metric['label']) : __((string) ($metric['key'] ?? '')); ?>
                    <div class="kpi">
                        <span class="kpi__value"><?= e((string) ($metric['value'] ?? '')) ?></span>
                        <span class="kpi__label"><?= e($mLabel) ?></span>
                    </div>
                <?php endforeach; ?>
            </div>
        <?php endif; ?>

        <?php if ($shots !== []): ?>
            <section class="block">
                <div class="block__head reveal"><h2 class="block__title" data-i18n="project.gallery"><?= t('project.gallery') ?></h2></div>
                <div class="gallery reveal">
                    <?php foreach ($shots as $img): ?>
                        <button type="button" class="gallery__shot" data-zoom="<?= e(upload_url((string) $img)) ?>">
                            <img src="<?= e(upload_url((string) $img)) ?>" alt="" loading="lazy" decoding="async" data-fit>
                        </button>
                    <?php endforeach; ?>
                </div>
            </section>
        <?php endif; ?>

        <?php if (trim(tr($project['summary'] ?? '')) !== ''): ?>
            <section class="block">
                <div class="block__head reveal"><h2 class="block__title" data-i18n="project.about"><?= t('project.about') ?></h2></div>
                <p class="prose reveal"><?= nl2br(e(tr($project['summary'] ?? ''))) ?></p>
            </section>
        <?php endif; ?>

        <?php if ($stack !== []): ?>
            <section class="block">
                <div class="block__head reveal"><h2 class="block__title" data-i18n="project.tech"><?= t('project.tech') ?></h2></div>
                <div class="chips chips--accent reveal">
                    <?php foreach ($stack as $tech): ?><span class="chip"><?= e((string) $tech) ?></span><?php endforeach; ?>
                </div>
            </section>
        <?php endif; ?>
    </div>
</section>
<?php
    return (string) ob_get_clean();
}

