/* ------------------------------------------------------------------
   BOG'LANISH — pastdan chiqadigan oynada (sheet)
   ------------------------------------------------------------------ */

/* ------------------------------------------------------------------
   MENYU — barcha bo'limlar (sheet)
   ------------------------------------------------------------------ */

/* ##################################################################
   v6 — VIZUAL ASSETLAR (img/ papkasi)
   Har bir rasm ikki o'lchamda va ikki formatda: <kalit>-<en>.avif/.webp
   Fayl topilmasa — komponent rasmsiz (ikonka bilan) chiqadi.
   ################################################################## */

const IMG_DIR = 'img';
/** CDN'dagi rasmlar ro'yxati (img/ papkasi hostingda bo'lmasa ishlatiladi): kalit => kengliklar. */
const HERO_MEDIA_URL = 'https://696f540674d5d.xvest3.ru/AKBARTECHuz/uz/';

const IMG_MANIFEST = ['about' => [768, 1536], 'contact' => [768, 1536], 'experience' => [768, 1536], 'hero' => [768, 1536], 'projects' => [768, 1536], 'services' => [768, 1536], 'skills' => [768, 1536], 'svc-1c' => [480, 960], 'svc-ai-agents' => [480, 960], 'svc-ai-apps' => [480, 960], 'svc-api' => [480, 960], 'svc-automation' => [480, 960], 'svc-bpa' => [480, 960], 'svc-chatbots' => [480, 960], 'svc-database' => [480, 960], 'svc-motion' => [480, 960], 'svc-telegram' => [480, 960], 'svc-websites' => [480, 960]];

/** Rasm CDN manzili (index.php → 'img_cdn'); bo'sh bo'lsa faqat lokal img/ va uploads/. */
function img_cdn(): string
{
    return rtrim(trim((string) cfg('img_cdn', '')), '/');
}
/** Kalit prefiksi => [eni, bo'yi] nisbati (width/height atributlari uchun). */
const IMG_RATIOS = ['svc-' => [4, 3], 'pj-' => [3, 2], '' => [16, 9]];

/** Kalit uchun mavjud kengliklar (kichikdan kattaga). */
function img_widths(string $key): array
{
    static $cache = [];
    if (!preg_match('/^[a-z0-9-]{2,60}$/', $key)) {
        return [];
    }
    if (!isset($cache[$key])) {
        $widths = [];
        foreach ((array) glob(__DIR__ . '/' . IMG_DIR . '/' . $key . '-*.webp') as $file) {
            if (preg_match('/-(\d{3,4})\.webp$/', (string) $file, $m)) {
                $widths[] = (int) $m[1];
            }
        }
        sort($widths);
        if ($widths === [] && ($key === 'hero' || img_cdn() !== '') && isset(IMG_MANIFEST[$key])) {
            $widths = IMG_MANIFEST[$key];
        }
        $cache[$key] = $widths;
    }
    return $cache[$key];
}

function img_ratio(string $key): array
{
    foreach (IMG_RATIOS as $prefix => $ratio) {
        if ($prefix !== '' && strpos($key, $prefix) === 0) {
            return $ratio;
        }
    }
    return IMG_RATIOS[''];
}

function img_file_url(string $key, int $width, string $ext): string
{
    $file = $key . '-' . $width . '.' . $ext;
    if ($key === 'hero' && $ext === 'webp' && in_array($width, IMG_MANIFEST['hero'], true)
        && !is_file(__DIR__ . '/' . IMG_DIR . '/' . $file)) {
        return HERO_MEDIA_URL . $file;
    }
    if (img_cdn() !== '' && !is_file(__DIR__ . '/' . IMG_DIR . '/' . $file)) {
        return img_cdn() . '/' . rawurlencode($file);
    }
    return base_path() . '/' . IMG_DIR . '/' . $key . '-' . $width . '.' . $ext . '?v=' . cfg('version', '1.0.0');
}

/**
 * <picture>: AVIF → WebP, responsive srcset, lazy loading.
 * $sizes — brauzerga rasm ekranda qancha joy egallashini aytadi.
 */
function pic(string $key, string $class = '', string $sizes = '100vw', bool $eager = false, string $alt = ''): string
{
    $widths = img_widths($key);
    if ($widths === []) {
        return '';
    }
    [$rw, $rh] = img_ratio($key);
    $largest = (int) end($widths);
    $set = static function (string $ext) use ($key, $widths): string {
        return implode(', ', array_map(static fn (int $w): string => img_file_url($key, $w, $ext) . ' ' . $w . 'w', $widths));
    };
    $hasAvif = is_file(__DIR__ . '/' . IMG_DIR . '/' . $key . '-' . $largest . '.avif')
        || ($key !== 'hero' && img_cdn() !== '' && isset(IMG_MANIFEST[$key]));

    return '<picture class="' . e($class) . '">'
        . ($hasAvif ? '<source type="image/avif" srcset="' . e($set('avif')) . '" sizes="' . e($sizes) . '">' : '')
        . '<source type="image/webp" srcset="' . e($set('webp')) . '" sizes="' . e($sizes) . '">'
        . '<img src="' . e(img_file_url($key, $largest, 'webp')) . '" alt="' . e($alt) . '" width="' . $largest
        . '" height="' . (int) round($largest * $rh / $rw) . '" decoding="async"'
        . ($eager ? ' fetchpriority="high"' : ' loading="lazy"') . '>'
        . '</picture>';
}

function service_image_key(array $service): string
{
    $key = (string) ($service['image'] ?? '');
    return $key !== '' ? $key : 'svc-' . (string) ($service['id'] ?? '');
