function project_image_key(array $project): string
{
    $key = (string) ($project['image'] ?? '');
    return $key !== '' ? $key : 'pj-' . (string) ($project['slug'] ?? '');
}

/** Admin panel uchun: img/ papkasidagi tayyor rasmlar ro'yxati (prefiks bo'yicha). */
function img_library(string $prefix): array
{
    $keys = [];
    foreach ((array) glob(__DIR__ . '/' . IMG_DIR . '/' . $prefix . '*.webp') as $file) {
        if (preg_match('/\/(' . preg_quote($prefix, '/') . '[a-z0-9-]+)-\d{3,4}\.webp$/', (string) $file, $m)) {
            $keys[$m[1]] = true;
        }
    }
    if (img_cdn() !== '') {
        foreach (array_keys(IMG_MANIFEST) as $key) {
            if (strpos($key, $prefix) === 0) {
                $keys[$key] = true;
            }
        }
    }
    $keys = array_keys($keys);
    sort($keys);
    return $keys;
}

