/** Faoliyat va ko'nikmalar: har bir qatorning nusxasi video kabi uzluksiz aylanish uchun. */
function view_partials_capabilityreel(array $__d = []): string
{
    $activityCovers = ['database' => 'accounting', 'bot' => 'agents', 'bar-chart' => 'analytics'];
    $skillCovers = [
        'ai engineering' => 'ai-engineering',
        'ai agent development' => 'agent-development',
        'intelligent automation' => 'automation',
        '1c automation' => '1c-automation',
        'api integration' => 'api',
        'database engineering' => 'database',
        'telegram bot development' => 'telegram-bot',
        'telegram mini app development' => 'mini-app',
        'web application development' => 'web',
        'business process automation' => 'process',
        'ai-powered systems' => 'ai-systems',
        'motion design & motion video' => 'motion',
    ];
    $fallbackCovers = [
        'bot' => 'agents', 'message-circle' => 'telegram-bot', 'send' => 'telegram-bot',
        'smartphone' => 'mini-app', 'video' => 'motion', 'database' => 'database',
        'workflow' => 'process', 'globe' => 'web', 'zap' => 'automation',
    ];

    $activity = [];
    foreach (content_activities() as $item) {
        $title = trim(tr($item['title'] ?? ''));
        if ($title !== '') {
            $cover = $activityCovers[(string) ($item['icon'] ?? '')] ?? 'process';
            $activity[] = ['title' => $title, 'cover' => $cover];
        }
    }
    $featuredSkills = [
        'analytics' => ['uz' => 'Google Sheets avtomatlashtirish', 'en' => 'Google Sheets automation', 'ru' => 'Автоматизация Google Sheets'],
        '1c-automation' => ['uz' => 'Didox integratsiyasi', 'en' => 'Didox integration', 'ru' => 'Интеграция с Didox'],
        'process' => ['uz' => 'Logistika avtomatlashtirish', 'en' => 'Logistics automation', 'ru' => 'Автоматизация логистики'],
        'telegram-bot' => ['uz' => '100+ Telegram guruhini tahlil qilish', 'en' => 'Analysis of 100+ Telegram groups', 'ru' => 'Анализ 100+ групп Telegram'],
    ];
    $skills = [];
    $featuredTitles = [];
    foreach ($featuredSkills as $cover => $titles) {
        $skills[] = ['title' => tr($titles), 'cover' => $cover];
        foreach ($titles as $title) {
            $featuredTitles[mb_strtolower($title)] = true;
        }
    }
    foreach (content_competencies() as $item) {
        $title = trim((string) $item);
        $key = mb_strtolower($title);
        if ($title !== '' && !isset($featuredTitles[$key])) {
            $cover = $skillCovers[$key] ?? $fallbackCovers[skill_icon($title)] ?? 'ai-engineering';
            $skills[] = ['title' => $title, 'cover' => $cover];
        }
    }
    $rows = ['home.reel_activity' => $activity, 'home.reel_skills' => $skills];
    ob_start();
    ?>
<section class="block capability-reel" aria-labelledby="capability-title">
    <div class="capability-reel__head reveal">
        <div>
            <h2 class="block__title" id="capability-title" data-i18n="home.reel_title"><?= t('home.reel_title') ?></h2>
        </div>
    </div>
    <?php foreach ($rows as $label => $items): ?>
        <?php if ($items === []) { continue; } ?>
        <?php $repeat = count($items) > 1; ?>
        <div class="capability-reel__row<?= $label === 'home.reel_skills' ? ' capability-reel__row--skills' : '' ?><?= $repeat ? ' capability-reel__row--loop' : '' ?>">
            <div class="capability-reel__row-head">
                <h3 class="capability-reel__label" data-i18n="<?= e($label) ?>"><?= t($label) ?></h3>
                <?php if ($repeat): ?>
                    <button type="button" class="capability-reel__next" data-reel-next
                            aria-label="<?= t('onb.next') ?>"><?= icon('chevron-right', 17) ?></button>
                <?php endif; ?>
            </div>
            <div class="capability-reel__viewport" tabindex="0" role="region" aria-label="<?= t($label) ?>">
                <div class="capability-reel__track" style="--reel-duration: <?= max(32, count($items) * 4) ?>s">
                    <?php for ($copy = 0; $copy < ($repeat ? 2 : 1); $copy++): ?>
