/** Kompetensiya nomiga mos ikonka (kalit so'z bo'yicha). */
function skill_icon(string $name): string
{
    $map = [
        'agent' => 'bot', 'chatbot' => 'message-circle', 'telegram' => 'send', 'mini app' => 'smartphone',
        'motion' => 'video', 'video' => 'video', '1c' => 'database', 'database' => 'database', 'api' => 'workflow',
        'web' => 'globe', 'automation' => 'zap', 'process' => 'workflow', 'engineering' => 'cpu', 'ai' => 'brain-circuit',
    ];
    $lower = mb_strtolower($name);
    foreach ($map as $needle => $icon) {
        if (mb_strpos($lower, $needle) !== false) {
            return $icon;
        }
    }
    return 'sparkles';
}

