/* ##################################################################
   AKBARTECH — KONTENT QATLAMI
   Profil, tajriba, xizmatlar, havolalar. Standart qiymatlar
   data_source() da; admin panel → "Kontent" da saqlangani ustun turadi
   (store/content). Hech narsa o'chirilmaydi — faqat ustidan yoziladi.
   ################################################################## */

/** Admin panelda tahrirlanadigan kontent bo'limlari. */
const CONTENT_KEYS = ['profile', 'jobs', 'activities', 'competencies', 'platforms', 'directions', 'services', 'links', 'faq', 'hero'];

/** Hero fon videolari soni (admin panel cheklovi). */
const HERO_VIDEOS_MAX = 6;

/** Loyiha kategoriyalari (kalit => ko'rinadigan nom). */
const PROJECT_CATS = [
    'ai-agents'  => 'AI Agents',
    'automation' => 'Automation',
    'websites'   => 'Websites',
    'mobile'     => 'Mobile Apps',
    'bots'       => 'Telegram Bots',
    'motion'     => 'Motion Design',
];

/** Loyiha holatlari — tarjima kaliti: project.status.<kod>. */
const PROJECT_STATUSES = ['done', 'progress', 'concept'];

const ORDER_SERVICE_OTHER = 'other';

function content_profile(): array      { return (array) (content_all()['profile'] ?? []); }
function content_jobs(): array         { return array_values((array) (content_all()['jobs'] ?? [])); }
function content_activities(): array   { return array_values((array) (content_all()['activities'] ?? [])); }
function content_competencies(): array { return array_values((array) (content_all()['competencies'] ?? [])); }
function content_platforms(): array    { return array_values((array) (content_all()['platforms'] ?? [])); }
function content_directions(): array   { return array_values((array) (content_all()['directions'] ?? [])); }
function content_faq(): array          { return array_values((array) (content_all()['faq'] ?? [])); }

function content_hero_mode(): string
{
    $hero = (array) (content_all()['hero'] ?? []);
    return (string) ($hero['mode'] ?? (empty($hero['videos']) ? 'off' : 'custom'));
}

/** Hero fon videolari: admin havolalari yoki ilova bilan berilgan videolar. */
function content_hero_videos(bool $customOnly = false): array
{
    $out = [];
    foreach ((array) ((content_all()['hero'] ?? [])['videos'] ?? []) as $url) {
        $url = trim((string) $url);
        if ($url !== '' && preg_match('#^https://#i', $url) && !in_array($url, $out, true)) {
            $out[] = $url;
        }
    }
    if ($customOnly || content_hero_mode() === 'custom') {
        return array_slice($out, 0, HERO_VIDEOS_MAX);
    }
    if (content_hero_mode() === 'off') {
        return [];
    }

    $out = [];
    foreach (['studio.mp4', 'details.mp4'] as $file) {
        $local = 'media/' . $file;
        $out[] = is_file(__DIR__ . '/' . $local) ? asset($local) : HERO_MEDIA_URL . $file;
    }
    return $out;
}

/** Havolalar: saqlangan → index.php dagi $CONFIG → bo'sh. */
function content_links(): array
{
    $links = (array) (content_all()['links'] ?? []);
    $channel = trim((string) ($links['channel'] ?? ''));
    $support = ltrim(trim((string) ($links['support'] ?? '')), '@');

    return [
        'channel' => $channel !== '' ? $channel : (string) cfg('channel', ''),
        'support' => $support !== '' ? $support : ltrim((string) cfg('support', ''), '@'),
        'phone'   => trim((string) ($links['phone'] ?? '')),
        'youtube' => trim((string) ($links['youtube'] ?? '')),
    ];
}

function channel_url(): string
{
    return content_links()['channel'];
}

/** "https://t.me/AKBARTECHuz" → "@AKBARTECHuz". */
function link_handle(string $url): string
{
    $path = trim((string) parse_url($url, PHP_URL_PATH), '/');
    if ($path === '') {
        return $url;
    }
    return str_starts_with($path, '@') ? $path : '@' . $path;
}

function service_find(string $id): ?array
{
    if ($id === '') {
        return null;
    }
    foreach (content_services() as $service) {
        if ((string) ($service['id'] ?? '') === $id) {
            return $service;
        }
    }
    return null;
}

/** Loyihaning kategoriya kaliti. Eski yozuvlarda matndan taxmin qilinadi. */
function project_cat(array $project): string
{
    $cat = (string) ($project['cat'] ?? '');
    if (isset(PROJECT_CATS[$cat])) {
        return $cat;
    }

    $legacy = mb_strtolower(implode(' ', array_map('strval', (array) ($project['category'] ?? []))));
    $guess = [
        'bots'       => ['bot', 'telegram', 'mini app'],
        'motion'     => ['motion', 'video', 'animatsi', 'анимац'],
        'automation' => ['avtomat', 'automat', 'автомат', '1c', '1с'],
        'mobile'     => ['mobil', 'mobile', 'мобил'],
        'websites'   => ['web', 'sayt', 'сайт', 'веб'],
        'ai-agents'  => ['agent', 'агент'],
    ];
    foreach ($guess as $key => $needles) {
        foreach ($needles as $needle) {
            if (mb_strpos($legacy, $needle) !== false) {
                return $key;
            }
        }
    }
    return '';
}

function project_cat_label(array $project): string
{
    $cat = project_cat($project);
    return $cat !== '' ? PROJECT_CATS[$cat] : tr($project['category'] ?? '');
}

function project_status(array $project): string
{
    $status = (string) ($project['status'] ?? '');
    return in_array($status, PROJECT_STATUSES, true) ? $status : '';
}

/** Qidiruv uchun: nom, tavsif va texnologiyalar bitta kichik harfli satrda. */
function project_search_text(array $project): string
{
    $parts = [
        (string) ($project['name'] ?? ''),
        tr($project['tagline'] ?? ''),
        project_cat_label($project),
        implode(' ', array_map('strval', (array) ($project['stack'] ?? []))),
    ];
    return mb_strtolower(trim(implode(' ', $parts)));
}

/** Profil rasmi: admin panelda yuklangan → papkadagi akbar-photo.jpg → yo'q. */
function profile_photo_url(): string
{
    $photo = (string) (content_profile()['photo'] ?? '');
    if ($photo !== '') {
        return upload_url($photo);
    }
    return local_file('akbar-photo.jpg') !== null ? asset('akbar-photo.jpg') : '';
}

function profile_initials(): string
{
    $name = trim((string) (content_profile()['name'] ?? ''));
    $letters = '';
    foreach (preg_split('/\s+/u', $name) ?: [] as $word) {
        $letters .= mb_strtoupper(mb_substr($word, 0, 1));
    }
    return $letters !== '' ? mb_substr($letters, 0, 2) : 'A';
}

/** Matnni escape qiladi va *yulduzcha* orasidagini gradient span'ga o'raydi. */
function accent_html(string $text): string
{
    $safe = e($text);
    return (string) preg_replace('/\*([^*]+)\*/u', '<span class="grad">$1</span>', $safe);
}

/** Ko'p qatorli matn → ro'yxat (bo'sh qatorlarsiz). */
function text_lines(string $text): array
{
    return array_values(array_filter(array_map('trim', preg_split('/\R/u', $text) ?: []), static fn (string $l): bool => $l !== ''));
}

/* ------------------------------------------------------------------
   v5 ko'chirish: darslar interfeysdan ajratildi. Kurs ma'lumotlari
   (videolar, progress, vazifalar, sertifikatlar) O'CHIRILMAYDI —
   store/ dagi fayllar joyida qoladi va bir marta store/archive_v4/
   papkasiga nusxalanadi.
   ------------------------------------------------------------------ */
const ARCHIVE_STORES = ['videos', 'progress', 'tasks', 'certs', 'course', 'projects', 'orders', 'messages', 'users', 'settings'];

function migrate_v5(): void
{
    if (!store_available() || (string) settings_get('migrated', '') === 'v5') {
        return;
    }

    $dir = store_dir();
    $target = $dir . '/archive_v4';
    if (!is_dir($target) && !@mkdir($target, 0750, true) && !is_dir($target)) {
        return; // keyingi so'rovda qayta urinadi
    }

    $copied = [];
    foreach (ARCHIVE_STORES as $name) {
        $source = $dir . '/' . $name . '.php';
        if (!is_file($source)) {
            continue;
        }
        $copy = $target . '/' . $name . '.php';
        if (!is_file($copy) && !@copy($source, $copy)) {
            return; // nusxa olinmadi — belgi qo'yilmaydi, keyingi so'rovda qayta urinadi
        }
        $copied[] = $name;
    }

    settings_set(['migrated' => 'v5', 'migrated_at' => date('c'), 'archive_v4' => $copied]);
}


/**
 * v6.6 bir martalik yangilanish: admin panelda oldin saqlangan kontent standart
 * matnlarni to'sib qo'ymasligi uchun tajriba, bio va video tartibi yangilanadi.
 */
function migrate_v66(): void
{
    if (!store_available() || (string) settings_get('content_rev', '') === 'v66') {
        return;
    }
    $defaults = (array) (data_all()['content'] ?? []);
    $ok = store_update('content', static function (array $all) use ($defaults): array {
        if (isset($all['jobs'])) {
            $all['jobs'] = $defaults['jobs'] ?? [];
        }
        if (isset($all['profile']) && is_array($all['profile'])) {
            $all['profile']['bio'] = $defaults['profile']['bio'] ?? ($all['profile']['bio'] ?? []);
        }
        if (isset($all['hero']['videos']) && is_array($all['hero']['videos'])) {
            $first = (string) (($defaults['hero']['videos'] ?? [''])[0] ?? '');
            $list = array_values(array_filter($all['hero']['videos'], static fn ($u) => (string) $u !== $first));
            $all['hero']['videos'] = $first !== '' ? array_merge([$first], $list) : $list;
        }
        return $all;
    });
    if ($ok) {
        unset($GLOBALS['__content_cache']);
        settings_set(['content_rev' => 'v66']);
    }
}


/**
 * v6.7: admin panelda saqlangan loyihalar ro'yxati bo'lsa ham CITRIC.UZ loyihasi bir marta
 * boshiga qo'shiladi (ro'yxatda allaqachon bo'lsa — tegilmaydi).
 */
function migrate_v67(): void
{
    if (!store_available() || (string) settings_get('projects_rev', '') === 'v68') {
        return;
    }
    $stored = store_read('projects');
    if ($stored !== []) {
        $entry = null;
        foreach ((array) (data_all()['content']['projects'] ?? []) as $p) {
            if ((string) ($p['slug'] ?? '') === 'citric-uz') { $entry = $p; break; }
        }
        $exists = false;
        $stored = array_values($stored);
        foreach ($stored as $i => $p) {
            if ((string) ($p['slug'] ?? '') === 'citric-uz') {
                $exists = true;
                // Avvalgi versiyadagi fayl nomlari Google Drive havolalariga almashtiriladi
                if ($entry !== null && !preg_match('#^https://#', (string) ($p['cover'] ?? ''))) {
                    $stored[$i]['cover'] = $entry['cover'];
                    $stored[$i]['shots'] = $entry['shots'];
                }
                break;
            }
        }
        $list = $exists ? $stored : ($entry !== null ? array_merge([$entry], $stored) : $stored);
        if (!projects_save($list)) {
            return; // keyingi so'rovda qayta urinadi
        }
    }
    unset($GLOBALS['__projects_cache']);
    settings_set(['projects_rev' => 'v68']);
}

