/**
 * AKBARTECH tarjimalari — eski lug'at ustiga yoziladi (uch tilda bir xil
 * kalitlar). Darslarga oid eski guruhlar lug'atdan chiqarib tashlanadi.
 */
function data_source(): array
{
    $data = data_source_base();

    foreach (brand_lang() as $locale => $tree) {
        $base = (array) ($data['lang'][$locale] ?? []);
        foreach (['course', 'cert', 'tutorials', 'onb', 'stat'] as $legacy) {
            unset($base[$legacy]);
        }
        unset($base['home']['motivation']);
        $data['lang'][$locale] = array_replace_recursive($base, $tree);
    }

    return $data;
}

