/* ==================================================================
   ASOSIY OQIM
   ================================================================== */

/**
 * Bitta savolga javob. Mini app va bot shu funksiyadan foydalanadi.
 * @return array{ok:bool, text:string, refs:list<array>, mode:string, error?:string}
 */
function ai_answer(string $key, bool $trusted, string $locale, string $surface, string $message, array $history, array $meta = []): array
{
    $settings = ai_settings();
    $message = trim(mb_substr($message, 0, AI_MAX_INPUT));

    if ($message === '') {
        return ['ok' => false, 'text' => ai_limit_text('empty', $locale), 'refs' => [], 'mode' => 'notice', 'error' => 'empty'];
    }
    if (!$settings['enabled']) {
        return ['ok' => false, 'text' => ai_limit_text('disabled', $locale), 'refs' => [], 'mode' => 'notice', 'error' => 'disabled'];
    }

    $limit = ai_limit_check($key, $trusted, $settings);
    if ($limit !== null) {
        return ['ok' => false, 'text' => ai_limit_text($limit, $locale), 'refs' => [], 'mode' => 'notice', 'error' => $limit];
    }

    $messages = ai_clean_history($history);
    $messages[] = ['role' => 'user', 'text' => $message];

    $started = microtime(true);
    $result = ai_complete($settings, ai_system_prompt($locale, $surface), $messages);
    $ms = (int) round((microtime(true) - $started) * 1000);

    if ($result['ok']) {
        ai_limit_commit($key);
        $parsed = ai_extract_refs($result['text']);
        ai_log($meta + ['src' => $surface, 'q' => mb_substr($message, 0, 400), 'a' => mb_substr($parsed['text'], 0, 600), 'ok' => true, 'ms' => $ms, 'model' => $settings['model']]);
        return ['ok' => true, 'text' => $parsed['text'], 'refs' => $parsed['refs'], 'mode' => 'ai'];
    }

    error_log('[AKBARTECH AI] ' . $result['error']);
    ai_log($meta + ['src' => $surface, 'q' => mb_substr($message, 0, 400), 'a' => '', 'ok' => false, 'err' => $result['error'], 'ms' => $ms, 'model' => $settings['model']]);

    $fallback = ai_fallback($message, $locale);
    return ['ok' => true, 'text' => $fallback['text'], 'refs' => $fallback['refs'], 'mode' => 'fallback', 'error' => $result['error'] === 'not_configured' ? 'not_configured' : 'provider'];
}

/** Mini app'dan kelgan so'rov. */
function ai_chat_for_app(array $session, string $message, array $history): array
{
    $trusted = !empty($session['trusted']) && (int) $session['user']['id'] > 0;
    $key = $trusted ? 'tg:' . (int) $session['user']['id'] : client_ip_key();

    // Juda tez-tez yuborishdan himoya (bot/skript): 6 ta / 20 soniya
    if (!rate_hit('ai_burst', $key, 6, 20)) {
        return ['ok' => false, 'status' => 429, 'text' => ai_limit_text('limit_hour', $session['locale']), 'refs' => [], 'mode' => 'notice', 'error' => 'burst'];
    }

    $answer = ai_answer($key, $trusted, $session['locale'], 'app', $message, $history, [
        'uid'  => $trusted ? (int) $session['user']['id'] : 0,
        'name' => display_name($session['user']),
    ]);
    unset($answer['status']);
    return $answer;
}

/* ==================================================================
   TELEGRAM UCHUN FORMATLASH
   ================================================================== */

/** Yengil Markdown → Telegram HTML. */
function ai_to_telegram_html(string $text): string
{
    $blocks = [];
    $text = preg_replace_callback('/```[a-zA-Z0-9_+\-]*\n?(.*?)```/s', static function (array $m) use (&$blocks): string {
        $blocks[] = '<pre>' . htmlspecialchars(rtrim($m[1]), ENT_NOQUOTES, 'UTF-8') . '</pre>';
        return "\x00" . (count($blocks) - 1) . "\x00";
    }, $text) ?? $text;

    $text = htmlspecialchars($text, ENT_NOQUOTES, 'UTF-8');
    $text = preg_replace('/`([^`\n]+)`/', '<code>$1</code>', $text) ?? $text;
    $text = preg_replace('/\*\*([^*\n]+)\*\*/', '<b>$1</b>', $text) ?? $text;
    $text = preg_replace('/^\s*[-*]\s+/m', '• ', $text) ?? $text;

    return preg_replace_callback('/\x00(\d+)\x00/', static fn (array $m): string => $blocks[(int) $m[1]] ?? '', $text) ?? $text;
}

/** Bot uchun qisqa suhbat xotirasi (har chat uchun oxirgi 6 xabar). */
function ai_thread_get(int $chatId): array
{
    $threads = store_read('ai_threads');
    $row = (array) ($threads[(string) $chatId] ?? []);
    if (time() - (int) ($row['ts'] ?? 0) > 6 * 3600) {
        return [];
    }
    return (array) ($row['m'] ?? []);
}

function ai_thread_push(int $chatId, string $question, string $answer): void
{
    store_update('ai_threads', static function (array $threads) use ($chatId, $question, $answer): array {
        $key = (string) $chatId;
        $row = (array) ($threads[$key] ?? []);
        $messages = time() - (int) ($row['ts'] ?? 0) > 6 * 3600 ? [] : (array) ($row['m'] ?? []);
        $messages[] = ['role' => 'user', 'text' => mb_substr($question, 0, 800)];
        $messages[] = ['role' => 'assistant', 'text' => mb_substr($answer, 0, 1200)];
        $threads[$key] = ['ts' => time(), 'm' => array_slice($messages, -6)];

        if (count($threads) > 3000) {
            uasort($threads, static fn (array $a, array $b): int => (int) ($b['ts'] ?? 0) <=> (int) ($a['ts'] ?? 0));
            $threads = array_slice($threads, 0, 2500, true);
        }
        return $threads;
    });
}

function ai_thread_reset(int $chatId): void
{
    store_update('ai_threads', static function (array $threads) use ($chatId): array {
        unset($threads[(string) $chatId]);
        return $threads;
    });
}

