/**
 * TezMind.uz — TELEGRAM BOT
 *
 * /start, buyruqlar, aloqa, darsliklar, loyihalar, TezMind AI javoblari,
 * botni ulash (webhook) va xabar tarqatish (bosqichma-bosqich).
 */


/* ==================================================================
   BOT API
   ================================================================== */

/** Telegram Bot API (JSON so'rov). Xato bo'lsa ham massiv qaytaradi. */
function bot_api(string $method, array $params = [], int $timeout = 15): array
{
    $token = bot_token();
    if ($token === '' || !str_contains($token, ':')) {
        return ['ok' => false, 'error_code' => 0, 'description' => 'bot_token yo‘q'];
    }

    $url = 'https://api.telegram.org/bot' . $token . '/' . $method;
    $payload = json_encode($params, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);

    if (function_exists('curl_init')) {
        $handle = curl_init($url);
        curl_setopt_array($handle, [
            CURLOPT_POST           => true,
            CURLOPT_POSTFIELDS     => $payload,
            CURLOPT_HTTPHEADER     => ['Content-Type: application/json'],
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CONNECTTIMEOUT => 6,
            CURLOPT_TIMEOUT        => $timeout,
        ]);
        $response = curl_exec($handle);
        $error = curl_error($handle);
        curl_close($handle);
    } else {
        $response = @file_get_contents($url, false, stream_context_create(['http' => [
            'method'        => 'POST',
            'header'        => "Content-Type: application/json\r\n",
            'content'       => $payload,
            'timeout'       => $timeout,
            'ignore_errors' => true,
        ]]));
        $error = $response === false ? 'network' : '';
    }

    $decoded = json_decode((string) $response, true);
    if (is_array($decoded)) {
        return $decoded;
    }
    return ['ok' => false, 'error_code' => 0, 'description' => $error !== '' ? $error : 'no response'];
}

function bot_app_url(string $open = ''): string
{
    $url = absolute_url(entry_url());
    return $open === '' ? $url : $url . '?open=' . rawurlencode($open);
}

/** Matn yuborish: HTML xato bersa — oddiy matn sifatida qayta yuboradi. */
function bot_send(int $chatId, string $html, ?array $keyboard = null, bool $preview = false): array
{
    $params = [
        'chat_id'    => $chatId,
        'text'       => mb_substr($html, 0, 4000),
        'parse_mode' => 'HTML',
        'link_preview_options' => ['is_disabled' => !$preview],
    ];
    if ($keyboard !== null) {
        $params['reply_markup'] = $keyboard;
    }
    $result = bot_api('sendMessage', $params);

    if (empty($result['ok']) && (int) ($result['error_code'] ?? 0) === 400 && stripos((string) ($result['description'] ?? ''), 'parse') !== false) {
        unset($params['parse_mode']);
        $params['text'] = html_entity_decode(strip_tags($params['text']), ENT_QUOTES, 'UTF-8');
        $result = bot_api('sendMessage', $params);
    }
    return $result;
}

function h(string $text): string
{
    return htmlspecialchars($text, ENT_NOQUOTES, 'UTF-8');
}

