function bot_main_keyboard(array $c): array
{
    $links = content_links();
    $rows = [
        [['text' => $c['open'], 'web_app' => ['url' => bot_app_url()]]],
        [['text' => $c['order'], 'web_app' => ['url' => bot_app_url('order')]]],
    ];
    $extra = [];
    if ($links['channel'] !== '') { $extra[] = ['text' => $c['channel'], 'url' => $links['channel']]; }
    if ($links['youtube'] !== '') { $extra[] = ['text' => $c['youtube'], 'url' => $links['youtube']]; }
    if ($extra !== []) { $rows[] = $extra; }
    if ($links['support'] !== '') { $rows[] = [['text' => $c['contact'], 'url' => support_url()]]; }
    return ['inline_keyboard' => $rows];
}

/** /aloqa: to'ldirilgan havolalar ro'yxati va tugmalari. */
function bot_send_contacts(int $chatId, array $c): void
{
    $links = content_links();
    $lines = [$c['contacts_h'], ''];
    $rows = [];
    if ($links['support'] !== '') {
        $lines[] = $c['l_tg'] . ': @' . h($links['support']);
        $rows[] = [['text' => $c['contact'], 'url' => support_url()]];
    }
    if ($links['channel'] !== '') {
        $lines[] = $c['l_channel'] . ': ' . h($links['channel']);
        $rows[] = [['text' => $c['channel'], 'url' => $links['channel']]];
    }
    if ($links['phone'] !== '') {
        $lines[] = $c['l_phone'] . ': ' . h(phone_pretty($links['phone']));
    }
    $rows[] = [['text' => $c['order'], 'web_app' => ['url' => bot_app_url('order')]]];
    bot_send($chatId, implode("\n", $lines), ['inline_keyboard' => $rows]);
}

function bot_send_services(int $chatId, array $c): void
{
    $lines = [$c['services_h'], ''];
    foreach (content_services() as $service) {
        $lines[] = '• <b>' . h(tr($service['title'] ?? '')) . '</b> — ' . h(tr($service['text'] ?? ''));
    }
    bot_send($chatId, implode("\n", $lines), ['inline_keyboard' => [
        [['text' => $c['services'], 'web_app' => ['url' => bot_app_url('services')]]],
        [['text' => $c['order'], 'web_app' => ['url' => bot_app_url('order')]]],
    ]]);
}

/* ==================================================================
   FOYDALANUVCHILAR (bot orqali kelganlar)
   ================================================================== */

function bot_lead_touch(int $chatId, array $from, array $patch = []): array
{
    $record = [];
    store_update('bot_leads', static function (array $all) use ($chatId, $from, $patch, &$record): array {
        $key = (string) $chatId;
        $row = (array) ($all[$key] ?? []);
        $now = date('c');

        $name = trim(strip_tags((string) ($from['first_name'] ?? '') . ' ' . (string) ($from['last_name'] ?? '')));
        $row['id']         = $chatId;
        $row['name']       = $name !== '' ? mb_substr($name, 0, 80) : (string) ($row['name'] ?? '');
        $row['username']   = mb_substr(strip_tags((string) ($from['username'] ?? ($row['username'] ?? ''))), 0, 60);
        $row['lang']       = substr((string) ($from['language_code'] ?? ($row['lang'] ?? '')), 0, 5);
        if (empty($row['started_at'])) {
            $legacy = $row['updated_at'] ?? null; // eski formatda vaqt soni bo'lgan
            $row['started_at'] = is_numeric($legacy) ? date('c', (int) $legacy) : $now;
        }
        $row['last_at']    = $now;
        $row['msgs']       = (int) ($row['msgs'] ?? 0) + 1;
        $row['blocked']    = false;
        unset($row['stage'], $row['updated_at']);

        foreach ($patch as $k => $v) { $row[$k] = $v; }
        $all[$key] = $row;
        $record = $row;
        return $all;
    });
    return $record;
}

function bot_lead_mark_blocked(int $chatId, bool $blocked): void
{
    store_update('bot_leads', static function (array $all) use ($chatId, $blocked): array {
        $key = (string) $chatId;
        if (isset($all[$key])) {
            $all[$key]['blocked'] = $blocked;
            $all[$key]['last_at'] = date('c');
        }
        return $all;
    });
}

/** Tarqatma uchun barcha qabul qiluvchilar (ilova + bot), bloklaganlarsiz. */
function bot_recipients(): array
{
    $ids = [];
    foreach (store_read('users') as $user) {
        $id = (int) ($user['tg_id'] ?? $user['id'] ?? 0);
        if ($id > 0 && empty($user['blocked'])) { $ids[$id] = true; }
    }
    foreach (store_read('bot_leads') as $key => $lead) {
        $id = (int) ($lead['id'] ?? $key); // eski yozuvlarda id faqat kalitda
        if ($id > 0) {
            if (!empty($lead['blocked'])) { unset($ids[$id]); continue; }
            $ids[$id] = true;
        }
    }
    return array_map('intval', array_keys($ids));
}

/* ==================================================================
   WEBHOOK
   ================================================================== */

function bot_webhook_secret(): string
{
    $key = (string) cfg('setup_key', '');
    if ($key !== '') {
        return hash('sha256', $key);
    }
    $token = bot_token();
    return $token === '' ? '' : hash_hmac('sha256', 'akbartech-webhook-v1', $token);
}

function bot_webhook(): void
{
    $expected = bot_webhook_secret();
    $sent = request_header('X-Telegram-Bot-Api-Secret-Token');
    if ($expected === '' || $sent === '' || !hash_equals($expected, $sent)) {
        http_response_code(403);
        return;
    }

    $raw = (string) file_get_contents('php://input');

    // Telegram javob kechiksa qayta yuboradi — darhol "OK" deymiz.
    send_json(['ok' => true]);
    finish_response();
    @set_time_limit(90);

    $update = json_decode($raw, true);
    if (!is_array($update)) {
        return;
    }

    // Bir yangilanish ikki marta kelsa — ikkinchisini e'tiborsiz qoldiramiz.
    $updateId = (int) ($update['update_id'] ?? 0);
    $duplicate = false;
    store_update('bot_updates', static function (array $seen) use ($updateId, &$duplicate): array {
        if (in_array($updateId, $seen, true)) {
            $duplicate = true;
            return $seen;
        }
        $seen[] = $updateId;
        return array_slice($seen, -300);
    });
    if ($duplicate) {
        return;
    }

    if (isset($update['my_chat_member'])) {
        $member = $update['my_chat_member'];
        if (($member['chat']['type'] ?? '') === 'private') {
            $status = (string) ($member['new_chat_member']['status'] ?? '');
            bot_lead_mark_blocked((int) ($member['chat']['id'] ?? 0), in_array($status, ['kicked', 'left'], true));
        }
        return;
    }

    $message = $update['message'] ?? null;
    if (is_array($message)) {
        bot_on_message($message);
    }
}

function bot_on_message(array $message): void
{
    $chat = (array) ($message['chat'] ?? []);
    $chatId = (int) ($chat['id'] ?? 0);
    if ($chatId === 0 || ($chat['type'] ?? '') !== 'private') {
        return;
    }

    $from = (array) ($message['from'] ?? []);
    $locale = lang_sanitize((string) ($from['language_code'] ?? ''));
    lang_use($locale);
    $c = bot_copy($locale);

    $lead = bot_lead_touch($chatId, $from);
    $firstName = trim(strip_tags((string) ($from['first_name'] ?? ''))) ?: 'do‘st';

    $text = trim((string) ($message['text'] ?? ''));
    $command = '';
    if ($text !== '' && $text[0] === '/') {
        $command = strtolower(explode('@', explode(' ', $text, 2)[0], 2)[0]);
    } elseif (strcasecmp($text, 'admin') === 0) {
        $command = '/admin';
    }

    $adminId = (int) cfg('admin_tg_id', 0);
    $isAdmin = $chatId === $adminId && (int) ($from['id'] ?? 0) === $adminId;
    if ($command === '/admin') {
        if ($isAdmin) {
            bot_send_admin_summary($chatId);
        }
        return;
    }

    $verified = $isAdmin || trim((string) ($lead['phone'] ?? '')) !== '';

    // Kontakt ulashildi → raqam tasdiqlandi → mini app tugmalari
    if (isset($message['contact']) && is_array($message['contact'])) {
        $contact = $message['contact'];
        if ((int) ($contact['user_id'] ?? 0) !== (int) ($from['id'] ?? -1)) {
            bot_send($chatId, h($c['not_own']), bot_phone_keyboard($c));
            return;
        }
        $phone = '+' . ltrim(preg_replace('/[^0-9]/', '', (string) ($contact['phone_number'] ?? '')) ?? '', '+');
        $isNew = trim((string) ($lead['phone'] ?? '')) === '';
        bot_lead_touch($chatId, $from, ['phone' => mb_substr($phone, 0, 20), 'phone_verified' => true, 'verified_at' => date('c')]);
        bot_send($chatId, h($c['verified']), ['remove_keyboard' => true]);
        bot_enable_app($chatId);
        bot_send_welcome($chatId, $firstName, $c);
        if ($isNew) {
            bot_notify_new_lead($chatId, $from, $phone);
        }
        return;
    }

    // Raqam tasdiqlanmagan — avval telefon so'raladi (yordam va aloqa bundan mustasno)
    if (!$verified && !in_array($command, ['/help', '/aloqa', '/contact', '/support'], true)) {
        $prompt = ($command === '' && $text !== '') ? $c['ask_again'] : sprintf($c['ask_phone'], h($firstName));
        bot_send($chatId, $prompt, bot_phone_keyboard($c));
        return;
    }

    switch ($command) {
        case '/start':
        case '/menu':
            bot_enable_app($chatId);
            bot_send_welcome($chatId, $firstName, $c);
            return;

        case '/help':
            bot_send($chatId, $c['help'], bot_main_keyboard($c));
            return;

        case '/aloqa':
        case '/contact':
        case '/support':
            bot_send_contacts($chatId, $c);
            return;

        case '/xizmatlar':
        case '/services':
            bot_send_services($chatId, $c);
            return;

        case '/buyurtma':
        case '/order':
            bot_send($chatId, h($c['order_t']), ['inline_keyboard' => [
                [['text' => $c['order'], 'web_app' => ['url' => bot_app_url('order')]]],
            ]]);
            return;

        // Eski buyruqlar (darslar interfeysdan ajratilgan) — bosh menyu ko'rsatiladi
        case '/darslar':
        case '/lessons':
            bot_send_welcome($chatId, $firstName, $c);
            return;

        case '/loyihalar':
        case '/projects':
            bot_send_projects($chatId, $c);
            return;

        case '/yangi':
        case '/new':
            ai_thread_reset($chatId);
            bot_send($chatId, h($c['reset']));
            return;
    }

    if ($command !== '') {
        bot_send_welcome($chatId, $firstName, $c);
        return;
    }

    if ($text === '') {
        bot_send($chatId, h($c['non_text']));
        return;
    }

    bot_answer_with_ai($chatId, $from, $locale, $text, $c, $lead);
}

/** "Raqamni yuborish" tugmasi (Telegram raqamni o'zi tasdiqlab yuboradi). */
function bot_phone_keyboard(array $c): array
{
    return [
        'keyboard'                => [[['text' => $c['share_btn'], 'request_contact' => true]]],
        'resize_keyboard'         => true,
        'is_persistent'           => true,
        'input_field_placeholder' => $c['share_ph'],
    ];
}

const BOT_MENU_BUTTON_TEXT = '🚀 Ilovani ochish';

/** Pastki menyu tugmasi: mini app'ni ochadi. */
function bot_menu_button(): array
{
    return ['type' => 'web_app', 'text' => BOT_MENU_BUTTON_TEXT, 'web_app' => ['url' => bot_app_url()]];
}

/** Shu foydalanuvchi uchun pastki menyu tugmasini mini app'ga aylantiradi. */
function bot_enable_app(int $chatId): void
{
    bot_api('setChatMenuButton', [
        'chat_id'     => $chatId,
        'menu_button' => bot_menu_button(),
    ], 8);
}

/** Adminga: yangi obunachi raqamini tasdiqladi. */
function bot_notify_new_lead(int $chatId, array $from, string $phone): void
{
    $adminId = (int) cfg('admin_tg_id', 0);
    if ($adminId <= 0 || $adminId === $chatId) {
        return;
    }
    $name = trim(strip_tags((string) ($from['first_name'] ?? '') . ' ' . (string) ($from['last_name'] ?? '')));
    $user = (string) ($from['username'] ?? '');
    $total = count(array_filter(store_read('bot_leads'), static fn ($l): bool => trim((string) ($l['phone'] ?? '')) !== ''));
    bot_send($adminId, "🆕 <b>Yangi obunachi</b>\n\n👤 " . h($name !== '' ? $name : 'Nomsiz')
        . ($user !== '' ? ' (@' . h($user) . ')' : '') . "\n📞 " . h($phone) . "\n\nJami tasdiqlangan: <b>" . $total . '</b>');
}

function bot_send_welcome(int $chatId, string $name, array $c): void
{
    // Faqat matn — rasm yuborilmaydi (tezroq va toza).
    bot_send($chatId, sprintf($c['welcome'], h($name)), bot_main_keyboard($c));
}

function bot_send_projects(int $chatId, array $c): void
{
    $lines = [$c['projects_h'], ''];
    foreach (array_slice(projects_all(), 0, 12) as $project) {
        $lines[] = '• <b>' . h((string) ($project['name'] ?? '')) . '</b> — ' . h(tr($project['tagline'] ?? ''));
    }
    bot_send($chatId, implode("\n", $lines), ['inline_keyboard' => [
        [['text' => $c['projects'], 'web_app' => ['url' => bot_app_url('projects')]]],
    ]]);
}

function bot_send_admin_summary(int $chatId): void
{
    $summary = stats_summary();
    $leads = count(store_read('bot_leads'));
    $text = "<b>📊 AKBARTECH — qisqa hisobot</b>\n\n"
        . '👥 Ilova foydalanuvchilari: <b>' . (int) $summary['users'] . "</b>\n"
        . '🤖 Bot obunachilari: <b>' . $leads . "</b>\n"
        . '📈 Bugungi tashriflar: <b>' . (int) $summary['today'] . "</b>\n"
        . '📦 Yangi buyurtmalar: <b>' . orders_new_count() . '</b>';
    bot_send($chatId, $text, ['inline_keyboard' => [
        [['text' => '🛠 Admin panel', 'web_app' => ['url' => absolute_url(base_path() . '/admin.php?tg=1')]]],
    ]]);
}

function bot_answer_with_ai(int $chatId, array $from, string $locale, string $text, array $c, array $lead): void
{
    $settings = ai_settings();
    if (!$settings['enabled'] || !$settings['in_bot']) {
        bot_send($chatId, h($c['ai_off']), bot_main_keyboard($c));
        return;
    }

    bot_api('sendChatAction', ['chat_id' => $chatId, 'action' => 'typing'], 5);

    $answer = ai_answer('tg:' . $chatId, true, $locale, 'bot', $text, ai_thread_get($chatId), [
        'uid'  => $chatId,
        'name' => (string) ($lead['name'] ?? ''),
    ]);

    if ($answer['mode'] === 'ai') {
        ai_thread_push($chatId, $text, $answer['text']);
    }

    $rows = [];
    foreach ($answer['refs'] as $ref) {
        if ($ref['type'] === 'project') {
            $rows[] = [['text' => '🗂 ' . mb_substr($ref['title'], 0, 50), 'web_app' => ['url' => bot_app_url('project-' . $ref['id'])]]];
        }
    }
    if ($answer['mode'] !== 'ai') {
        $rows[] = [['text' => $c['contact'], 'url' => support_url()]];
    }

    bot_send($chatId, ai_to_telegram_html($answer['text']), $rows !== [] ? ['inline_keyboard' => $rows] : null);
}

/* ==================================================================
   BOTNI ULASH (webhook, menyu tugmasi, buyruqlar, tavsif)
   ================================================================== */

function bot_setup(): array
{
    $results = [];
    $me = bot_api('getMe');
    $results['getMe'] = $me;
    if (empty($me['ok'])) {
        return ['ok' => false, 'error' => 'Bot tokeni noto‘g‘ri yoki Telegram javob bermadi: ' . (string) ($me['description'] ?? ''), 'details' => $results];
    }

    $appUrl = bot_app_url();
    if (!str_starts_with($appUrl, 'https://')) {
        return ['ok' => false, 'error' => 'Telegram faqat https manzilni qabul qiladi (SSL sertifikat kerak)', 'details' => $results];
    }

    $secret = bot_webhook_secret();
    if ($secret === '') {
        return ['ok' => false, 'error' => 'Telegram bot tokeni saqlanmagan.', 'details' => $results];
    }

    $results['webhook'] = bot_api('setWebhook', [
        'url'                  => $appUrl . '?r=webhook',
        'secret_token'         => $secret,
        'allowed_updates'      => ['message', 'my_chat_member'],
        'max_connections'      => 20,
        'drop_pending_updates' => false,
    ]);

    // Standart menyu — hamma uchun "🚀 Ilovani ochish" (mini app).
    $results['menu_button'] = bot_api('setChatMenuButton', ['menu_button' => bot_menu_button()]);
    $adminId = (int) cfg('admin_tg_id', 0);
    if ($adminId > 0) {
        bot_enable_app($adminId);
    }

    $commands = [
        'uz' => [['start', 'Bosh menyu'], ['xizmatlar', 'Xizmatlar'], ['loyihalar', 'Loyihalar'], ['buyurtma', 'Buyurtma berish'], ['aloqa', 'Bog‘lanish'], ['yangi', 'AI bilan yangi suhbat'], ['help', 'Yordam']],
        'ru' => [['start', 'Главное меню'], ['services', 'Услуги'], ['projects', 'Проекты'], ['order', 'Оставить заказ'], ['contact', 'Связаться'], ['new', 'Новый диалог с AI'], ['help', 'Помощь']],
        'en' => [['start', 'Main menu'], ['services', 'Services'], ['projects', 'Projects'], ['order', 'Place an order'], ['contact', 'Contact'], ['new', 'New AI chat'], ['help', 'Help']],
    ];
    foreach ($commands as $lang => $list) {
        $payload = ['commands' => array_map(static fn (array $c): array => ['command' => $c[0], 'description' => $c[1]], $list)];
        $results['commands_' . $lang] = bot_api('setMyCommands', $payload + ['language_code' => $lang]);
        if ($lang === 'uz') {
            $results['commands_default'] = bot_api('setMyCommands', $payload);
        }
    }

    $descriptions = [
        'uz' => ['AKBARTECH — AI Engineering & Intelligent Automation. AI agentlar, biznes avtomatlashtirish, Telegram botlar va zamonaviy raqamli yechimlar. /start ni bosing!', 'AI agentlar · Avtomatlashtirish · Raqamli yechimlar'],
        'ru' => ['AKBARTECH — AI Engineering & Intelligent Automation. AI-агенты, автоматизация бизнеса, Telegram-боты и современные цифровые решения. Нажмите /start!', 'AI-агенты · Автоматизация · Цифровые решения'],
        'en' => ['AKBARTECH — AI Engineering & Intelligent Automation. AI agents, business automation, Telegram bots and modern digital solutions. Tap /start!', 'AI agents · Automation · Digital solutions'],
    ];
    foreach ($descriptions as $lang => $pair) {
        bot_api('setMyDescription', ['description' => $pair[0], 'language_code' => $lang]);
        bot_api('setMyShortDescription', ['short_description' => $pair[1], 'language_code' => $lang]);
    }
    bot_api('setMyDescription', ['description' => $descriptions['uz'][0]]);
    bot_api('setMyShortDescription', ['short_description' => $descriptions['uz'][1]]);

    $ok = !empty($results['webhook']['ok']) && !empty($results['menu_button']['ok']);
    if ($ok) {
        settings_set([
            'bot_connected' => bot_fingerprint(),
            'bot_username_live' => (string) ($me['result']['username'] ?? ''),
            'bot_connected_at' => date('c'),
        ]);
    }

    return [
        'ok'      => $ok,
        'bot'     => '@' . (string) ($me['result']['username'] ?? ''),
        'app_url' => $appUrl,
        'next'    => $ok ? 'Tayyor! Telegramda botga /start yozing.' : 'Xatolarni quyida ko‘ring.',
        'error'   => $ok ? '' : (string) ($results['webhook']['description'] ?? $results['menu_button']['description'] ?? 'Noma’lum xato'),
        'details' => $results,
    ];
}

/** Hozirgi token + kalit + manzil — o'zgarsa bot qayta ulanadi. */
function bot_fingerprint(): string
{
    $key = (string) cfg('setup_key', '');
    // Empty-key installations must re-register with the derived secret.
    $fingerprintKey = $key !== '' ? $key : 'token-webhook-v1';
    return hash('sha256', 'v5|' . bot_token() . '|' . $fingerprintKey . '|' . bot_app_url());
}

function bot_webhook_info(): array
{
    $info = bot_api('getWebhookInfo', [], 10);
    return is_array($info['result'] ?? null) ? $info['result'] : ['error' => (string) ($info['description'] ?? 'Telegram javob bermadi')];
}

/* ==================================================================
   XABAR TARQATISH — bosqichma-bosqich, to'xtab qolmaydi
   ================================================================== */

function broadcast_create(array $message): array
{
    $photo = '';
    if (($message['image'] ?? '') !== '') {
        $photo = absolute_url(upload_url((string) $message['image']));
    }
    $job = [
        'id'         => bin2hex(random_bytes(6)),
        'message_id' => (string) ($message['id'] ?? ''),
        'title'      => (string) ($message['title'] ?? ''),
        'text'       => (string) ($message['text'] ?? ''),
        'link'       => (string) ($message['link'] ?? ''),
        'photo'      => $photo,
        'app_url'    => bot_app_url(),
        'recipients' => bot_recipients(),
        'pos'        => 0,
        'sent'       => 0,
        'failed'     => 0,
        'blocked'    => 0,
        'done'       => false,
        'created_at' => date('c'),
    ];
    if ($job['recipients'] === []) {
        $job['done'] = true;
    }

    store_update('broadcasts', static function (array $jobs) use ($job): array {
        array_unshift($jobs, $job);
        return array_slice($jobs, 0, 10);
    });
    return $job;
}

function broadcast_find(string $id): ?array
{
    foreach (store_read('broadcasts') as $job) {
        if ((string) ($job['id'] ?? '') === $id) {
            return $job;
        }
    }
    return null;
}

/** Faol (tugamagan) tarqatma. */
function broadcast_active(): ?array
{
    foreach (store_read('broadcasts') as $job) {
        if (empty($job['done'])) {
            return $job;
        }
    }
    return null;
}

function broadcast_public(array $job): array
{
    $total = count((array) ($job['recipients'] ?? []));
    return [
        'id'      => (string) $job['id'],
        'title'   => (string) $job['title'],
        'total'   => $total,
        'pos'     => (int) $job['pos'],
        'sent'    => (int) $job['sent'],
        'failed'  => (int) $job['failed'],
        'blocked' => (int) $job['blocked'],
        'done'    => !empty($job['done']),
        'percent' => $total > 0 ? (int) floor((int) $job['pos'] / $total * 100) : 100,
    ];
}

/** Bir qadam: ~8 soniya ichida iloji boricha ko'p xabar yuboradi. */
function broadcast_step(string $id, float $budget = 8.0): array
{
    $lockPath = (store_dir() ?? sys_get_temp_dir()) . '/broadcast_run.lock';
    $lock = @fopen($lockPath, 'c');
    if ($lock === false || !flock($lock, LOCK_EX | LOCK_NB)) {
        return ['ok' => true, 'busy' => true, 'job' => ($job = broadcast_find($id)) ? broadcast_public($job) : null];
    }

    $job = broadcast_find($id);
    if ($job === null) {
        flock($lock, LOCK_UN);
        fclose($lock);
        return ['ok' => false, 'error' => 'not_found'];
    }

    $started = microtime(true);
    $recipients = (array) $job['recipients'];
    $total = count($recipients);
    $wait = 0;
    $blockedIds = [];

    $html = ($job['title'] !== '' ? '<b>' . h($job['title']) . "</b>\n\n" : '') . h($job['text']);
    $rows = [];
    if ($job['link'] !== '' && preg_match('#^https?://#i', $job['link'])) {
        $rows[] = [['text' => '🔗 Batafsil', 'url' => $job['link']]];
    }
    $rows[] = [['text' => '🚀 Ilovani ochish', 'web_app' => ['url' => $job['app_url']]]];
    $keyboard = ['inline_keyboard' => $rows];

    while (empty($job['done']) && $job['pos'] < $total && (microtime(true) - $started) < $budget) {
        $chatId = (int) $recipients[$job['pos']];

        if ($job['photo'] !== '') {
            $result = bot_api('sendPhoto', [
                'chat_id' => $chatId, 'photo' => $job['photo'], 'caption' => mb_substr($html, 0, 1024),
                'parse_mode' => 'HTML', 'reply_markup' => $keyboard,
            ], 12);
        } else {
            $result = bot_api('sendMessage', [
                'chat_id' => $chatId, 'text' => mb_substr($html, 0, 4000), 'parse_mode' => 'HTML',
                'reply_markup' => $keyboard, 'link_preview_options' => ['is_disabled' => true],
            ], 12);
        }

        if (!empty($result['ok'])) {
            $job['sent']++;
        } else {
            $code = (int) ($result['error_code'] ?? 0);
            if ($code === 429) {
                $retry = (int) ($result['parameters']['retry_after'] ?? 5);
                if ($retry <= 3 && (microtime(true) - $started) + $retry < $budget) {
                    sleep($retry);
                    continue; // shu odamga qayta urinamiz
                }
                $wait = $retry;
                break;
            }
            if ($code === 403) {
                $job['blocked']++;
                $blockedIds[] = $chatId;
            } else {
                $job['failed']++;
            }
        }

        $job['pos']++;
        usleep(45000); // ~20 xabar/soniya — Telegram limitidan past
    }

    if ($job['pos'] >= $total) {
        $job['done'] = true;
        $job['finished_at'] = date('c');
    }

    store_update('broadcasts', static function (array $jobs) use ($job): array {
        foreach ($jobs as $i => $row) {
            if ((string) ($row['id'] ?? '') === $job['id']) {
                $jobs[$i] = $job;
            }
        }
        return $jobs;
    });

    if ($blockedIds !== []) {
        store_update('bot_leads', static function (array $all) use ($blockedIds): array {
            foreach ($blockedIds as $id) {
                if (isset($all[(string) $id])) {
                    $all[(string) $id]['blocked'] = true;
                }
            }
            return $all;
        });
        store_update('users', static function (array $all) use ($blockedIds): array {
            foreach ($blockedIds as $id) {
                if (isset($all[(string) $id])) {
                    $all[(string) $id]['blocked'] = true;
                }
            }
            return $all;
        });
    }

    flock($lock, LOCK_UN);
    fclose($lock);

    return ['ok' => true, 'wait' => $wait, 'job' => broadcast_public($job)];
}

