/* ==================================================================
   JAVOB YUBORISH
   ================================================================== */

function send_html(string $html, int $status = 200, bool $noStore = false): void
{
    if (!headers_sent()) {
        http_response_code($status);
        header('Content-Type: text/html; charset=UTF-8');
        header('X-Content-Type-Options: nosniff');
        header('Referrer-Policy: strict-origin-when-cross-origin');
        if ($noStore) {
            header('Cache-Control: no-store, max-age=0');
        }
    }
    echo $html;
}

/* ==================================================================
   ILOVA QOBIG'I
   ================================================================== */

function route_app(): void
{
    $session = session_resolve();
    $unread = unread_count((int) $session['user']['id']);

    $boot = [
        'base'        => base_path(),
        'entry'       => entry_url(),
        'version'     => (string) cfg('version'),
        'locale'      => $session['locale'],
        'theme'       => $session['theme'],
        'locales'     => (array) cfg('locales'),
        'themes'      => (array) cfg('themes'),
        'screens'     => (array) cfg('screens'),
        'channel'     => channel_url(),
        'support'     => support_url(),
        'botUsername' => bot_username(),
        'appName'     => (string) cfg('name'),
        'verified'    => $session['verified'],
        'allowGuest'  => (bool) cfg('allow_guest', true),
        'prefs'       => $session['prefs'],
        'unread'      => $unread,
        'open'        => substr(preg_replace('/[^a-z0-9_-]/i', '', (string) ($_GET['open'] ?? '')) ?? '', 0, 80),
        'i18n'        => lang_dict($session['locale']),
    ];

    send_html(view('layout', [
        'session' => $session,
        'boot'    => $boot,
        'unread'  => $unread,
        'home'    => render_screen('home', $session),
    ]), 200, true);
}

/** Bitta ekran — mijoz tomonidagi marshrutizator uchun HTML bo'lagi. */
function route_screen(): void
{
    $session = session_resolve();
    $name = (string) ($_GET['name'] ?? 'home');

    if (!in_array($name, (array) cfg('screens'), true)) {
        send_html('', 404, true);
        return;
    }

    switch ($name) {
        case 'messages':
            send_html(render_screen('messages', $session, [
                'messages' => messages_for_user((int) $session['user']['id']),
            ]), 200, true);
            return;

        case 'project':
            $project = content_project((string) ($_GET['slug'] ?? ''));
            if ($project === null) {
                send_html('', 404, true);
                return;
            }
            send_html(render_screen('project', $session, ['project' => $project]), 200, true);
            return;

        case 'order':
            $project = content_project((string) ($_GET['slug'] ?? ''));
            $service = (string) ($_GET['service'] ?? '');
            if ($service !== ORDER_SERVICE_OTHER && service_find($service) === null) {
                $service = '';
            }
            send_html(render_screen('order', $session, [
                'prefill_slug'    => $project['slug'] ?? '',
                'prefill_name'    => $project['name'] ?? '',
                'prefill_service' => $service,
            ]), 200, true);
            return;
    }

    send_html(render_screen($name, $session), 200, true);
}

