/** Splash paytida bajariladigan tanishuv. */
function route_session(): void
{
    $session = session_track();
    $user = $session['user'];
    $tgId = (int) $user['id'];

    send_json([
        'ok'       => true,
        'verified' => $session['verified'],
        'admin'    => session_is_admin($session),
        'user'     => [
            'id'         => $user['id'],
            'first_name' => $user['first_name'],
            'last_name'  => $user['last_name'],
            'username'   => $user['username'],
            'photo_url'  => $user['photo_url'],
            'is_premium' => $user['is_premium'],
            'name'       => display_name($user),
        ],
        'locale' => $session['locale'],
        'theme'  => $session['theme'],
        'prefs'  => $session['prefs'],
        'unread' => unread_count($tgId),
        'i18n'   => lang_dict($session['locale']),
    ]);

    // Profil rasmini javob yuborilgandan KEYIN yangilaymiz — splash kutmaydi.
    if ($session['verified'] && $tgId > 0) {
        finish_response();
        user_refresh_avatar($tgId);
    }
}

/** Til, ko'rinish va kalitlarni saqlash. */
function route_settings(): void
{
    $session = session_resolve();

    $locale = lang_sanitize((string) request_input('locale', $session['locale']));

    $theme = (string) request_input('theme', $session['theme']);
    if (!in_array($theme, (array) cfg('themes'), true)) {
        $theme = $session['theme'];
    }

    $incoming = request_input('prefs', []);
    $incoming = is_array($incoming) ? $incoming : [];

    $prefs = [
        'notifications' => (bool) ($incoming['notifications'] ?? $session['prefs']['notifications']),
        'haptics'       => (bool) ($incoming['haptics'] ?? $session['prefs']['haptics']),
        'motion'        => (bool) ($incoming['motion'] ?? $session['prefs']['motion']),
    ];

    $saved = false;
    if (!empty($session['trusted']) && (int) $session['user']['id'] > 0) {
        $saved = user_save_prefs((int) $session['user']['id'], $locale, $theme, $prefs);
    }

    lang_use($locale);

    send_json([
        'ok'        => true,
        'persisted' => $saved,
        'locale'    => $locale,
        'theme'     => $theme,
        'prefs'     => $prefs,
        'i18n'      => lang_dict($locale),
    ]);
}

/** Foydalanuvchi haqida saqlangan hamma narsani o'chiradi. */
function route_forget(): void
{
    $session = session_resolve();
    $tgId = (int) $session['user']['id'];

    if (empty($session['verified']) || $tgId <= 0) {
        send_json(['ok' => false, 'error' => 'unauthorized'], 401);
        return;
    }

    user_forget($tgId);
    send_json(['ok' => true]);
}

function route_messages(): void
{
    $session = session_resolve();
    $tgId = (int) $session['user']['id'];

    send_json([
        'ok'       => true,
        'messages' => messages_for_user($tgId),
        'unread'   => unread_count($tgId),
    ]);
}

function route_read(): void
{
    $session = session_resolve();
    $tgId = (int) $session['user']['id'];

    if (empty($session['trusted']) || $tgId <= 0) {
        send_json(['ok' => false, 'error' => 'unauthorized'], 401);
        return;
    }

    $id = (string) request_input('id', '');
    $ok = $id === 'all' ? messages_mark_all_read($tgId) : message_mark_read($tgId, $id);

    send_json(['ok' => $ok, 'unread' => unread_count($tgId)]);
}

/** "Buyurtma berish" formasi. Barcha maydonlar order_create() da qayta tekshiriladi. */
function route_order(): void
{
    if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
        send_json(['ok' => false, 'error' => 'method'], 405);
        return;
    }

    $session = session_resolve();
    $user = $session['user'];
    $trusted = !empty($session['trusted']);
    $tgId = $trusted ? (int) $user['id'] : 0;

    // Spam-himoya: IP bo'yicha 10 daqiqada 8 ta urinish (tasdiqlanganlar uchun ham).
    if (!rate_hit('order_ip', client_ip_key(), 8, 600)) {
        send_json(['ok' => false, 'error' => 'rate_limited'], 429);
        return;
    }

    // Username faqat tasdiqlangan Telegram profilidan olinadi (soxtalashtirib bo'lmaydi).
    $username = $trusted ? (string) ($user['username'] ?? '') : '';

    $result = order_create([
        'tg_id'        => $tgId,
        'idem'         => (string) request_input('idem', ''),
        'name'         => (string) request_input('name', ''),
        'username'     => $username,
        'service'      => (string) request_input('service', ''),
        'contact'      => (string) request_input('contact', ''),
        'budget'       => (string) request_input('budget', ''),
        'description'  => (string) request_input('description', ''),
        'project_slug' => (string) request_input('project_slug', ''),
    ]);

    if (!$result['ok']) {
        $status = ['rate_limited' => 429, 'validation' => 400, 'store_unavailable' => 500, 'save_failed' => 500];
        send_json($result, $status[(string) ($result['error'] ?? '')] ?? 422);
        return;
    }

    send_json($result, empty($result['duplicate']) ? 201 : 200);
}

/** AI yordamchi — mini app ichidagi suhbat. */
function route_ai(): void
{
    if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
        send_json(['ok' => false, 'error' => 'method'], 405);
        return;
    }

    $session = session_resolve();

    $history = request_input('history', []);
    $result = ai_chat_for_app($session, (string) request_input('message', ''), is_array($history) ? $history : []);

    send_json($result, $result['ok'] ? 200 : (int) ($result['status'] ?? 200));
}

/**
 * Tekshiruv sahifasi.
 *   .../index.php?r=health              — qisqa holat
 *   .../index.php?r=health&key=SETUP_KEY — to'liq ma'lumot
 */
function route_health(): void
{
    $files = ['index.php', 'admin.php'];
    $missing = [];
    foreach ($files as $file) {
        $path = local_path($file);
        if ($path === null || filesize($path) === 0) {
            $missing[] = $file;
        }
    }

    $ok = $missing === [] && store_available();
    $key = (string) ($_GET['key'] ?? '');
    $expected = (string) cfg('setup_key');

    if ($expected === '' || !hash_equals($expected, $key)) {
        send_json(['ok' => $ok, 'app' => (string) cfg('name'), 'version' => (string) cfg('version')]);
        return;
    }

    $token = bot_token();
    send_json([
        'ok'             => $ok,
        'app'            => (string) cfg('name'),
        'version'        => (string) cfg('version'),
        'php'            => PHP_VERSION,
        'php_ok'         => version_compare(PHP_VERSION, '7.4', '>='),
        'missing_files'  => $missing,
        'store_writable' => store_available(),
        'users_count'    => count(store_read('users')),
        'bot_leads'      => count(store_read('bot_leads')),
        'projects_count' => count(projects_all()),
        'migrated'       => (string) settings_get('migrated', ''),
        'bot_token_set'  => $token !== '' && str_contains($token, ':'),
        'ai_configured'  => ai_settings()['key'] !== '',
        'curl'           => function_exists('curl_init'),
        'gd'             => extension_loaded('gd'),
        'app_url'        => absolute_url(entry_url()),
        'time'           => date('c'),
    ]);
}

