/**
 * Botni ro'yxatdan o'tkazish. Brauzerda bir marta oching:
 * .../index.php?r=setup&key=SETUP_KEY
 * (Yoki admin panel → "Telegram bot" → "Botni ulash".)
 */
function route_setup(): void
{
    $key = (string) ($_GET['key'] ?? '');
    $expected = (string) cfg('setup_key');

    if ($expected === '' || !hash_equals($expected, $key)) {
        send_json(['ok' => false, 'error' => 'setup_key noto\'g\'ri'], 403);
        return;
    }

    $result = bot_setup();
    send_json($result, $result['ok'] ? 200 : 400);
}

