/* ==================================================================
   DIZAYN VA ANIMATSIYA — ilgari app.css / app.js bo'lgan fayllar.
   ?r=asset&f=app.css orqali uzoq muddatli kesh bilan beriladi.
   ================================================================== */

function asset_source(string $name): string
{
    switch ($name) {
        case 'app.css':  return app_css();
        case 'app.js':   return app_js();
    }
    return '';
}

function asset_version(string $name): string
{
    static $cache = [];
    return $cache[$name] ??= substr(md5(cfg('version') . asset_source($name)), 0, 10);
